    [2258] = {n="Busca pelos reagentes dos Ermos", d="Leve 5 Moelas de Urubu, 10 Presas de Coiote do Rochedo e 5 Estilhaços de Elemental da Rocha para Jarkal Limuno em Karrath, Ermos.", tgo={{"Urubu Faminto", "Urubu", "Urubu Gigante"}, {"Coiote do Rochedo", "Coiote Feroz do Rochedo", "Coiote Ancião do Rochedo"}, {"Elemental da Rocha", "Elemental Inferior da Rocha", "Elemental Maior da Rocha"}}},
    [2278] = {n="Os discos de platina", d="Fale com o vigia de pedra e descubra quais são os segredos da história antiga que ele guarda. Após aprender os segredos históricos, ative os Discos de Norgannon.", tgo={{"Guardião do Folclore de Norgannon"}}},
    [2280] = {n="Os discos de platina", d="Leve a versão em miniatura dos Discos de Norgannon para algum dos sábios no Penhasco do Trovão."},
    [2283] = {n="O resgate do colar", d="Procure um colar valioso na escavação de Uldaman e leve-o para Dran Droffers em Orgrimmar. O colar pode estar danificado.", tgo={{"Topógrafo de Umbraforja", "Rufião de Umbraforja", "Escavador de Umbraforja"}}},
    [2284] = {n="O resgate do colar 2 - A missão", d="Encontre uma pista do paradeiro das gemas nas profundezas de Uldaman."},
    [2318] = {n="Traduzindo o diário", d="Encontre alguém que consiga traduzir o diário do paladino. O local mais próximo que pode ter alguém que o faça é Karrath, nos Ermos."},
    [2338] = {n="Traduzindo o diário", d="Empreste o colar a Jarkal. Em troca, ele vai traduzir o diário para você."},
    [2339] = {n="Encontre as Gemas e a Fonte de Energia", d="Recupere todas as três gemas e uma fonte de energia para o colar de Uldaman e leve-as para Jarkal Limuno, em Karrath. Jarkal acredita que uma fonte de energia pode ser encontrada no constructo mais forte presente em Uldaman.\nDe acordo com o diário:\n* O rubi está escondido em uma área de Umbraforja protegida por barreiras.\n* O topázio está escondido numa urna em uma das áreas dos troggs, perto de alguns anões da Aliança.\n* A safira foi reclamada por Grimlok, o líder dos troggs.", tgo={{}, {"Grimlok"}, {}, {"Arkhaedas"}}, objs={"Baú de Umbraforja", "Urna Evidente"}},
    [2340] = {n="Entregue as gemas", d="Entregue o Colar e Gema Recuperados para Dran Droffers em Orgrimmar."},
    [2341] = {n="O resgate do colar 3 - O Retorno", d="Visite Jarkal Limuno em Karrath para ver se ele obteve sucesso."},
    [2342] = {n="Tesouros recuperados", d="Pegue o tesouro de Patrício Garreta no baú de sua família, que está no Saguão Sul de Uldaman, e entregue a ele na Cidade Baixa.", objs={"Baú da Família Garreta"}},
    [2378] = {n="Encontre a Mão Despedaçada", d="Vá até Orgrimmar e fale com Shenthul no Antro das Sombras."},
    [2379] = {n="Zando'zan", d="Fale com Zando'zan no Antro das Sombras."},
    [2381] = {n="Saqueando os saqueadores", d="Leve o Tesouro dos Mares do Sul para Wrenix, o Ignóbil, na Vila Catraca. Não se esqueça de pegar um B.E.C.A. e as Ferramentas de Ladrões no Aparato Mercadotrônico do Wrenix. Você precisará desses dois itens para cumprir a missão.\nCaso seja atacado por papagaios nada amigáveis, use o B.E.C.A!", tgo={{"Polly"}}},
    [2382] = {n="Wrenix da Vila Catraca", d="Viaje para a Vila Catraca e fale com Wrenix, o Ignóbil."},
    [2383] = {n="Pergaminho simples", d="Leia o Pergaminho Simples e fale com Frang no Vale das Provações."},
    [2418] = {n="Pedras de energia", d="Leve 8 Pedras de Energia de Dêntrio e 8 Pedras de Energia de An'Alleum para Bertolezo nos Ermos.", tgo={{"Topógrafo de Umbraforja", "Rufião de Umbraforja", "Escavador de Umbraforja"}, {"Topógrafo de Umbraforja", "Rufião de Umbraforja", "Escavador de Umbraforja"}}},
    [2458] = {n="Missão secreta", d="Vá à Torre da Empreendimentos S.A., ao norte do Charco de Lodo, e entre em contato com o agente secreto da Mão Despedaçada, o Capataz Arruela.\nQuando a torre estiver à vista, use o Sinalizador para anunciar sua chegada ao Capataz Arruela. Dispare DUAS vezes, depois aproxime-se do Capataz e faça a /continencia dos Mão Despedaçada.\nEstas ações devem ser executadas na ordem correta, já que Arruela vai atacar e eliminar qualquer pessoa que não reconheça."},
    [2460] = {n="A saudação dos Mão Despedaçada", d="Faça a Continência dos Mãos Despedaçada para Shenthul.", tgo={{"Shenthul"}}},
    [2478] = {n="Missão: possível, mas não provável", d="Roube a Chave da Torre do Capataz Biela e, em seguida, mate 2 Peões Mutantes da Empreendimentos S.A., 2 Patrulheiros da Empreendimentos S.A. e 2 Vigias da Empreendimentos S.A.\nArranque a cabeça do Capataz-chefe Gallywix, arrombe o cofre dele e roube o Esconderijo do Preparado Adulterado do Zanzil. Leve-o junto com a cabeça para Shenthul em Orgrimmar para receber mais instruções.", tgo={{"Peão Mutante da Empreendimentos S.A."}, {"Vigia da Empreendimentos S.A."}, {"Patrulheiro da Empreendimentos S.A."}, {"Capataz-chefe Puzik Gallywix"}, {"Capataz Biela"}, {}}, objs={"Cofre de Gallywix"}},
    [2479] = {n="A ajuda de Hinoto", d="Vá até a Serraria Tarren, que fica no Contraforte de Eira dos Montes, e entregue a Amostra do Preparado de Zanzil a Serguei Hinoto.\nPara chegar à Serraria Tarren, pegue o Zepelim até a Cidade Baixa e siga a estrada em direção ao sul além de Pinhaprata, rumo à Eira dos Montes. É só seguir as placas!"},
    [2480] = {n="A ajuda de Hinoto", d="Espere Serguei Hinoto concluir a cura."},
    [2521] = {n="A serviço de Kum'isha", d="Em suas jornadas pela Barreira do Inferno, caso encontre uma esfera de draenetista impecável, leve-a de volta para Kum'isha, o Colecionador.\nAtenção, essa pedra é um dos cristais mais raros de toda Azeroth. Qualquer criatura nestas terras poderia ter em seu poder uma esfera de draenetista impecável.\nVocê será recompensad<o/a> por cada esfera de draenetista impecável que conseguir.", tgo={{"Ogro de Malhorrendo", "Ogro-mago de Malhorrendo", "Brutamontes de Malhorrendo"}}},
    [2581] = {n="Mandíbulas de rasgarrindo", d="Traga três Mandíbulas de Rasgarrindo, dois Pulmões de Javali Destroçados e uma Tenaz de Escórpode para o Mago Sangrento Drazial.", tgo={{"Rasgarrindo Faminta", "Hiena Rasgarrindo", "Rasgarga"}, {"Javali Jubacinza", "Javiltusco", "Grunhido"}, {"Aguilhante Escorpóde", "Clack, o Aniquilador"}}},
    [2583] = {n="A vitalidade dos javalis", d="Leve 3 Pulmões de Javali Destroçado, 2 Tenazes de Escórpode e 1 Cérebro de Basilisco para o Mago Sangrento Drazial.", tgo={{"Javali Jubacinza", "Javiltusco", "Grunhido"}, {"Aguilhante Escorpóde", "Clack, o Aniquilador"}, {"Basilisco Itarrubra", "Cristalderme Itarrubra", "Olho da Morte"}}},
    [2585] = {n="Ataque decisivo", d="Leve 3 Tenazes de Escórpode, 2 Moelas de Abutre e 1 Pulmão de Javali Destroçado para o Mago Sangrento Drazial.", tgo={{"Aguilhante Escorpóde", "Clack, o Aniquilador"}, {"Matador Negro", "Bonepicker"}, {"Javali Jubacinza", "Javiltusco", "Grunhido"}}},
    [2601] = {n="A mordida do basilisco", d="Leve 10 Cérebros de Basilisco e 2 Moelas de Abutre para a Maga Sangrenta Lynnore.", tgo={{"Basilisco Itarrubra", "Cristalderme Itarrubra", "Olho da Morte"}, {"Matador Negro", "Bonepicker"}}},
    [2603] = {n="O vigor do abutre", d="Leve 10 Moelas de Abutre e 2 Mandíbulas de Rasgarrindo para a Maga Sangrenta Lynnore.", tgo={{"Matador Negro", "Bonepicker"}, {"Rasgarrindo Faminta", "Hiena Rasgarrindo", "Rasgarga"}}},
