    [2767] = {n="Resgate o OOX-22/FE!", d="Escolte o OOX-22/FE até a doca ao longo da Costa Esquecida, depois apresente-se a Olhatorto Obnótico na Angra do Butim."},
    [2768] = {n="Bastão divinomático", d="Leve o Bastão Divinomático ao Engenheiro-chefe Silvadágua em Geringontzan.", tgo={{"Sargento Bly"}}, star={"Anel da Confraria Maçom", {"ROGUE", "HUNTER", "DRUID"}}},
