    [2862] = {n="Patábua mole em guerra dura", d="Leve 10 Jubas de Gnoll Patábua para Hadoken Passo Veloz na Aldeia Mojache.", tgo={{"Mestiço Patábua", "Coureador Patábua", "Brutamontes Patábua"}}},
