    [4291] = {n="O olfato de Lar'korwi", d="Leve 2 Glândulas de Feromônio de Ravassauro para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", tgo={{"Lar'korwi Fêmea"}}},
    [4292] = {n="A isca para Lar'korwi", d="Use o conteúdo do Bornal do Torwa para evocar Lar'korwi e derrotá-lo. Então, leve a Cabeça do Lar'korwi para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Tabuletas dos Sete", d="Leve a Transcrição de Tabuleta para Maxwort Uberraio nas Estepes Ardentes.", objs={"Tabuletas dos Sete"}},
    [4300] = {n="Armas de gume de osso", d="Leve 8 Garras Brancas de Ravassauro para Sona'rima em Orgrimmar.", tgo={{"Ravassauro", "Ravassauro Corredor", "Ravassauro Caçador"}}},
    [4301] = {n="O poderoso U'cha", d="Leve Pelagem de U'cha para Torwa Mateiro na entrada da Cratera Un'Goro.", tgo={{"U'cha"}}},
    [4321] = {n="Entendendo tudo", d="Fale com J.D. Neri em um instante."},
    [4324] = {n="Yuka Parafuseta", d="Fale com Yuka Parafuseta nas Estepes Ardentes."},
    [4402] = {n="A surpresa de sabra do Galgar", d="Leve 10 Sabras para Galgar. Você lembra que ele disse que se encontram sabras perto dos cactos.", objs={"Sabra"}},
    [4449] = {n="Calça arriada!", d="Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora.", tgo={{"Geólogo Ferro Negro"}, {}}, objs={"Granito de Alterac", "Baú Gasto", "Baú Sólido"}},
    [4489] = {n="Evocar Corcel Vil", d="Fale com Strahad Farsan na Vila Catraca."},
    [4490] = {n="Evocar Corcel Vil", d="Fale com Strahad Farsan, na Vila Catraca, para aprender a habilidade de evocar um Corcel Vil."},
    [4491] = {n="O calor tá de matar", d="Leve Ringo até Espraga Froque, no Refúgio do Marshal.\nSe Ringo desmaiar, use o Cantil da Espraga para reanimá-lo."},
    [4492] = {n="Perdido!", d="Encontre Ringo no Pico Penacho de Fogo."},
    [4494] = {n="A marcha dos silitídeos", d="Fale com o Alquimista Almofarrista em Geringontzan."},
    [4496] = {n="Sururu na selva", d="Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.", tgo={{"Vespa Gorishi", "Gorishi Trabalhadora", "Gorishi Aniquiladora"}, {}}, objs={"Monte de Terra de Un'Goro"}},
    [4502] = {n="Atividade vulcânica", d="Colete 9 amostras das Cinzas de Un'Goro dos elementais de fogo ao redor do vulcão da Cratera Un'Goro, e leve-as para Fanny Quito, em Vila Catraca.", tgo={{"Elemental Calcinante", "Chama Viva", "Agni"}}},
    [4503] = {n="O Chislo quer voar!", d="Colete 8 Escamas de Dimetrodonte Palmado e 8 Escamas de Pterrordax Palmado para Chislo no Refúgio do Marshal.", tgo={{"Dimetrodonte Jovem", "Dimetrodonte", "Dimetrodonte Ancião"}, {"Pterrordax Jovem", "Pterrordax", "Pterrordax Frenético"}}},
    [4504] = {n="Supergrudento", d="Colete 12 amostras de Piche Supergrudento para Tran'rek em Geringontzan.", tgo={{"Monstro de Piche", "Tocaieiro de Piche", "Senhor do Piche"}}},
    [4505] = {n="Poço da Corrupção", d="Colete uma amostra de água corrompida do poço lunar dos Sátiros Flamejade e leve-a para Winna Perícon no Posto Peçonha.", objs={"Poço Lunar Corrompido"}},
    [4506] = {n="Dentes-de-sabre corrompidos", d="Leve o gatinho de Winna para o poço lunar corrompido, solte-o e depois o leve de volta para Winna.\nQuando retornar, clique no gato para deixá-lo com Winna."},
    [4521] = {n="Guardiões selvagens", d="Trull Ruinazar em Selva Maleva quer que você mate 15 Ferujas Furiosas e 15 Ferujas Maltrapilhas.", tgo={{"Feruja Furiosa"}, {"Feruja Maltrapilha"}}},
    [4542] = {n="Mensagem para a Aldeia Vento Livre", d="Leve a Mensagem Urgente ao Vigia do Rochedo Chifre Longo na Aldeia Vento Livre."},
    [4641] = {n="O seu lugar no mundo", d="Fale com Gornek. Kaltunk marcou o paradeiro dele no mapa e mencionou que ele morava no Covil, ao oeste."},
    [4724] = {n="Senhora do matilha", d="Mate Halycon, senhora da matilha dos Worgs Machado Sangrento.", tgo={{"Halycon"}}},
    [4726] = {n="Essência da Reprodução", d="Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.", objs={"Essência da Reprodução"}},
    [4729] = {n="Mascotes exóticas do Kibler", d="Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler."},
    [4737] = {n="Em busca de Menara Nihila", d="Fale com Menara Nihila nos Sertões."},
    [4739] = {n="Em busca de Menara Nihila", d="Fale com Menara Nihila nos Sertões."},
    [4742] = {n="Selo da Ascensão", d="Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan.\nOs generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento.", tgo={{"Grão-lorde Omokk"}, {"Senhor da Guerra Voone"}, {"Lorde Supremo Wyrmthalak"}, {"Bruto do Escudo Marcado", "Sentinela do Escudo Marcado", "Acólito do Escudo Marcado"}}},
    [4743] = {n="Selo da Ascensão", d="Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada.\nÉ nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser <rápido/rápida> para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!", objs={"Selo Forjado da Ascensão"}},
    [4767] = {n="Mantícora", d="Leve 10 Ovos de Mantícora de Alcândora para Elu, na Aldeia Vento Livre.", objs={"Ovo de Mantícora de Alcândora"}},
    [4768] = {n="A tabuleta de Pedranegra", d="Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath.", objs={"Tabuleta de Pedranegra"}},
    [4769] = {n="Vivian Latumba e a Tabuleta de Pedranegra", d="Fale com a Umbramante Vivian Latumba."},
    [4770] = {n="Vínculo fraterno", d="Escolte Pae'ka Monte Veloz para fora de Alcândora, depois converse com Motega Barba de Fogo, no Posto Confinalvo."},
    [4781] = {n="Componentes para um robessangre dourado encantado", d="Leve uma Barra de Ouro para Xizk Pontobom, na Selva do Espinhaço.", objs={"Baú Gasto", "Baú Sólido", "Caixa-forte da Aliança"}},
    [4782] = {n="Componentes para um robessangre dourado encantado", d="Fale com Menara Nihila, nos Sertões."},
    [4783] = {n="Componentes para um robessangre dourado encantado", d="Leve 10 Ampolas de Sangue de Furiódio e 1 Pedra Infernal Menor para Menara Nihila, nos Sertões.", tgo={{"Errante Furiódio", "Trapaceiro Furiódio", "Devoto Vil Furiódio"}, {"Infernal Menor", "Guardião do Portal Demoníaco"}}},
    [4784] = {n="Componentes para um robessangre dourado encantado", d="Leve Fio de Ouro de Qualidade, 2 Carvões Fumegantes e um Estilhaço de Alma para Menara Nihila, nos Sertões.", tgo={{"Xizk Pontobom"}, {"Exilado em Chamas"}, {}}},
    [4785] = {n="Fio de ouro de qualidade"},
    [4786] = {n="Veste prêt-à-porter", d="Espere até Menara Nihila concluir a sua veste e depois fale novamente com ela.", tgo={{"Menara Nihila"}}, star={"Robessangre Dourado Encantado", {"WARLOCK"}}},
    [4787] = {n="O ovo velho", d="Leve o Ovo Velho para Yeh'kinya, em Tanaris.", objs={"Ovo Velho"}},
    [4808] = {n="Felnok Molaço", d="Leve a Carta de Vera para Felnok Molaço."},
    [4809] = {n="Chifres de ventogelante", d="Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço.", tgo={{"Assolador de Ventogelante", "Quimera Ventogelante", "Assolador de Ventogelante"}}},
    [4810] = {n="Fale novamente com Vera", d="Leve o Pacote do Felnok para Vera Brequim, nas Estepes Ardentes."},
    [4821] = {n="Ovo alienígena", d="Leve o Ovo Alienígena a Hagar Casco de Raio, na Aldeia Vento Livre.", objs={"Ovo Alienígena"}},
    [4841] = {n="Pacifique o Centauro", d="Mate 12 Batedores Galath, 10 Cavalgantes Galath e 6 Ventilhões Galath, depois fale novamente com o Vigia do Rochedo Chifre Longo na Aldeia Vento Livre.", tgo={{"Batedor Galath"}, {"Cavalgante Galath"}, {"Ventilhã Galath"}}},
    [4842] = {n="Fontes estranhas", d="Siga as instruções de Bruna Covaneve, depois fale novamente com ela."},
    [4862] = {n="Nojento!", d="Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler.\nPelo nome, é de se pensar que eles fiquem perto das aranhas.", objs={"Ovo de Aranha do Pináculo"}},
    [4865] = {n="Selva da serpente", d="Relate suas descobertas a Motega Barba de Fogo."},
    [4881] = {n="Plano de assassinato", d="Alerte Kanati Nuvem Cinzenta, no Posto Confinalvo, do plano para assassiná-lo."},
    [4903] = {n="O comando do Senhor da Guerra", d="Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida.", tgo={{"Lorde Supremo Wyrmthalak"}, {"Grão-lorde Omokk"}, {"Senhor da Guerra Voone"}, {}}, objs={"Documentos Inconspícuos"}},
    [4904] = {n="Liberdade, liberdade", d="Escolte Lakota Cantéolo para fora do Pináculo da Nuvem Negra e depois fale com Thalia Couro Âmbar, na Aldeia Vento Livre."},
    [4921] = {n="Perdida em combate", d="Encontre a Mulher de Mankrik e depois fale novamente com ele na Encruzilhada.", tgo={{"Cadáver Arrebentado"}}},
    [4941] = {n="A sabedoria de Eitrigg", d="Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall.\nVocê se lembra de ter visto Eitrigg nos aposentos de Thrall."},
    [4961] = {n="A purificação do Orbe de Orahil", d="Mate o Demônio do Orbe, depois fale com Tabetha.", tgo={{"Demônio do Orbe"}}},
    [4962] = {n="Estilhaço de canisvil", d="Pegue o Rubi de Felhas e use-o em um dos Canisvis encontrados em Desolação. Depois de conseguir, leve o Rubi de Felhas e o Espírito de Canisvil Aprisionado de volta a Menara Nihila, nos Sertões.", tgo={{"Manávoro"}}},
    [4963] = {n="Estilhaço de infernal", d="Pegue a Esmeralda Infusa e use-a em um dos Infernais encontrados em Desolação. Depois de conseguir, leve a Esmeralda Infusa e o Espírito de Infernal Aprisionado de volta a Menara Nihila, nos Sertões.", tgo={{"Infernal Menor"}}},
    [4964] = {n="Orbe de Dar'Orathil concluído", d="Espere Menara Nihila completar o Orbe de Dar'Orathil e fale com ela novamente.", tgo={{"Menara Nihila"}}},
    [4966] = {n="Proteja Kanati Nuvem Cinzenta", d="Proteja Kanati Nuvem Cinzenta do ataque dos centauros.", tgo={{"Assassino Galath"}}},
    [4967] = {n="O conhecimento do Orbe de Orahil", d="Fale com Menara Nihila nos Sertões."},
    [4969] = {n="O conhecimento do Orbe de Orahil", d="Fale com Menara Nihila nos Sertões."},
    [4971] = {n="É questão de tempo", d="Use o Deslocador Temporal perto de um dos silos de Andorhal e desencave Parasitas Temporais.\nMate 15 Parasitas Temporais e depois devolva o Deslocador Temporal para Crona na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Parasita Temporal"}}},
    [4972] = {n="Contando o tempo", d="Encontre 5 Relógios de Andorhal, que estão em cofres em meio às ruínas da cidade. Regresse com eles até Crona, que está na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.", objs={"Cofre Pequeno"}},
    [4974] = {n="Pela Horda!", d="Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar.", tgo={{"Chefe Guerreiro Laceral Mão Negra"}}},
    [4975] = {n="O Orbe de Nor'Orahil concluído", d="Espere Menara Nihila completar o Orbe de Nor'Orahil e fale com ela novamente.", tgo={{"Menara Nihila"}}},
    [4976] = {n="Devolução do orbe purificado", d="Leve o Orbe Infernal Purificado a Menara Nihila nos Sertões."},
    [4981] = {n="Agente Biju", d="Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju."},
    [4982] = {n="Pertences da Biju", d="Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade.", objs={"Pertences de Biju"}},
    [4983] = {n="Relatório de reconhecimento de Biju", d="Leve o Relatório de Reconhecimento de Biju para o Grão-mestre Lexlort em Karrath."},
    [4984] = {n="A vida selvagem também sofre", d="Destrua 8 Lobos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Lobo Doente"}}},
    [4985] = {n="A vida selvagem também sofre", d="Destrua 8 Ursos-cinzentos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.", tgo={{"Urso-cinzento Doente"}}},
    [5021] = {n="Antes tarde do que nunca", d="As divagações da mulher fantasmagórica indicavam que ela precisava que um pacote fosse entregue. Ela afirmou que ele estava no mesmo lugar que seu cavalo. Quanto ao local onde o cavalo está ou onde o pacote deve ser entregue, continua sendo impossível entender o fantasma."},
    [5023] = {n="Antes tarde do que nunca", d="Fale com os Feitores Reais da Cidade Baixa para saber o paradeiro da Jeremias Pedravil. Geralmente tem um agente do censo perto do registro de guilda e tabardo."},
    [5041] = {n="Suprimentos para a Encruzilhada", d="Encontre e devolva os Caixotes de Suprimentos da Encruzilhada a Thork, nos Sertões.", objs={"Caixote de Suprimentos da Encruzilhada"}},
    [5049] = {n="O fado de Jeremias", d="Encontre a Jeremias Mascotte na Cidade Baixa e veja se, de fato, ele é Jeremias Pedravil. Se for, talvez ele possa querer o pacote que Janice Pedravil lhe mandou."},
    [5050] = {n="Pingente da Sorte", d="Devolva o Meio-pingente da Sorte para Janice Pedravil nas Terras Pestilentas Ocidentais."},
    [5051] = {n="Um só coração", d="Localize a outra metade do Pingente da Sorte em algum lugar da Fazenda Pedravil, nas Terras Pestilentas Ocidentais, e monte-o novamente.\nDê o Pingente da Sorte a Janice Pedravil, na Fazenda Pedravil, que fica nas Terras Pestilentas Ocidentais."},
    [5052] = {n="Estilhaços de Sangue de Agamaggan", d="Leve um Estilhaço de Sangue para Denterroto no Acampamento Taurajo, que fica nos Sertões.\nColete mais Estilhaços de Sangue se você quiser que ele o abençoe com o poder de Agamaggan.", tgo={{"Caçador Costagulha", "Rabdomante Costagulha", "Tecespinho Costagulha"}}},
    [5054] = {n="Úrsius, o Dentilhaço", d="Ventania Casco Escuro, de Visteterna, Hibérnia, quer que você mate Úrsius.", tgo={{"Úrsius"}}},
    [5058] = {n="Diário da Sra. Dalson"},
    [5059] = {n="Trancafiado", d="Saque de: Esqueleto Errante", tgo={{"Esqueleto Errante"}}},
    [5060] = {n="Trancafiado", d="Saque de: Fazendeiro Dalson", tgo={{"Fazendeiro Dalson"}}},
    [5062] = {n="Fogo sagrado", d="Reúna 10 punhados de Agave Incendia, depois consulte Magatha Temível Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.", objs={"Agave Incendia"}},
    [5064] = {n="Espiando os Temível Totem", d="Localize e recupere os três Bilhetes Secretos no Pináculo da Nuvem Negra.", objs={"Baú de Documentos"}},
    [5082] = {n="A ameaça dos Invernosos", d="Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos.", tgo={{"Desbravador Invernoso"}, {"Vigia do Covil dos Invernosos"}, {"Totêmico Invernoso"}}},
    [5083] = {n="Aguardente Invernosa", d="Leve o Frasco Vazio de Aguardente para Bruna Covaneve em Hibérnia."},
    [5084] = {n="Cedendo à corrupção", d="Investigue o acampamento dos pelursos Lenha Morta na parte norte de Selva Maleva para encontrar alguma pista."},
    [5085] = {n="Meleca misteriosa", d="Informe Bruna Covaneve sobre as suas descobertas."},
    [5086] = {n="Horrores tóxicos", d="Colha 3 Gotinhas de Horror Tóxico para Bruna Covaneve em Hibérnia.", tgo={{"Horror Tóxico"}}},
    [5087] = {n="Mensageiros Invernosos", d="Encontre os Mensageiros Invernosos e impeça-os de entregar o carregamento à Aldeia dos Invernosos.", tgo={{"Mensageiro Invernoso"}}},
    [5096] = {n="Distrações escarlate", d="Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando.\nPlante a bandeira do Flagelo no acampamento e fale novamente com o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais."},
    [5098] = {n="Você não vê as torres?", d="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.\nDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais.", tgo={{"Torre Um de Andorhal"}, {"Torre Dois de Andorhal"}, {"Torre Três de Andorhal"}, {"Torre Quatro de Andorhal"}}},
    [5121] = {n="Chefe Supremo Invernoso", d="Bruna Covaneve em Hibérnia quer que você derrote o Chefe Supremo Invernoso.", tgo={{"Chefe Supremo Invernoso"}}},
    [5122] = {n="O Medalhão da Fé", d="Usar/coletar: Cofre de Malor", objs={"Cofre de Malor"}},
    [5123] = {n="A peça final", d="Leve o Registro Escrito Grosseiramente para Bruna Covaneve em Hibérnia."},
    [5125] = {n="O ajuste de contas de Aurius"},
    [5147] = {n="PROCURA-SE: Arnak Temível Totem", d="Mate Arnak Temível Totem e leve uma prova de seu feito para o Vigia do Rochedo Chifre Longo, na Aldeia Vento Livre.", tgo={{"Arnak Temível Totem"}}},
    [5149] = {n="A boneca de Pâmela", d="Encontre a boneca de Pâmela."},
    [5151] = {n="Dispositivo hipercapacitador", d="Mate a fera e traga de volta o Dispositivo Hipercapacitador e a Chave da Jaula da Pantera para Vizlo Limpajunta.", tgo={{"Pantera Enfurecida"}}},
    [5152] = {n="Tia Marlene", d="Fale com Marlene, ao sul das Ruínas de Andorhal."},
    [5153] = {n="Uma historiadora estranha", d="Leve o Anel de Casamento do Josefo para Crona.", objs={"Monumento do Josefo Trilharrubra"}},
    [5154] = {n="Os Anais da Vila das Flechas", d="Leve os Anais da Vila das Flechas para Crona em Andorhal.", objs={"Tomo Mofado"}},
    [5155] = {n="Forças de Jaedenar", d="Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva.", tgo={{"Cão de Jaedenar"}, {"Guardião de Jaedenar"}, {"Adepto de Jaedenar"}, {"Sectário de Jaedenar"}}},
    [5156] = {n="Verificar a corrupção", d="Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva.", tgo={{"Fera Entrópica"}, {"Horror Entrópico"}}},
    [5157] = {n="Coletar a água corrompida", d="Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva.", objs={"Poço Lunar Corrompido de Jaedenar"}},
    [5158] = {n="À procura de auxílio espiritual", d="Leve a Água Corrompida do Poço Lunar para Islen Vidente da Água, nos Sertões."},
    [5159] = {n="O retorno da água purificada à Selva Maleva", d="Leve a Água Purificada do Poço Lunar para Greta Musgo no Casco, na Selva Maleva."},
    [5163] = {n="Eu yeti falar uma coisa...", d="Leve o Yeti Mecânico da Umi e assuste os amigos dela:\nLegacki, em Visteterna (Hibérnia),\nSguisha, em Geringontzan (Tanaris) e\nQuixxil, no Refúgio do Marshal (Cratera Un'Goro).\nQuando terminar, leve o Yeti Mecânico de volta para Umi.", tgo={{"Legacki"}, {"Sguisha"}, {"Quixxil"}}},
    [5165] = {n="Extinguindo as chamas da proteção", d="Use a Água Purificada do Poço Lunar para extinguir os quatro braseiros de proteção no interior da Fortaleza do Concílio das Sombras, em Selva Maleva, depois fale novamente com Greta Musgo no Casco, no Santuário Esmeralda.", objs={"Braseiro da Dor", "Braseiro da Malícia", "Braseiro do Sofrimento", "Braseiro do Ódio"}},
    [5211] = {n="Defensores da Vila das Flechas", d="Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.", tgo={{"Espírito da Vila das Flechas"}}},
    [5212] = {n="A carne não mente", d="Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.", tgo={{"Cadaver Assolado", "Cadáver Mutilado", "Carniçal da Peste"}}},
    [5213] = {n="O agente ativo", d="Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco.", objs={"Dados do Flagelo"}},
    [5214] = {n="O grande Ezra Carranca", d="Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço.", tgo={{"Fras Siabi"}}},
    [5228] = {n="Os caldeirões do Flagelo", d="Fale com a Sacerdotisa Sombria Vandis, em Baluarte, que fica nas Terras Pestilentas Ocidentais."},
    [5229] = {n="Alvo: Campo Pedravil", d="Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Bilevil"}}},
    [5230] = {n="Retorno a Baluarte", d="Leve a Garrafa do Campo Pedravil Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."},
    [5231] = {n="Alvo: Lágrimas de Dalson", d="Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Malvínio"}}},
    [5232] = {n="Retorno a Baluarte", d="Leve a Garrafa das Lágrimas de Dalson Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."},
    [5233] = {n="Alvo: Antro Repelente", d="Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Rainério"}}},
    [5234] = {n="Retorno a Baluarte", d="Leve a Garrafa do Antro Repelente Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."},
    [5235] = {n="Alvo: Aridez de Garrão", d="Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão.", tgo={{"Mestre da Caldeira Almafúria"}}},
    [5236] = {n="Retorno a Baluarte", d="Leve a Garrafa da Aridez de Garrão Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."},
    [5238] = {n="Missão cumprida!", star={"Espada Curta Valente", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="Tio Carlin", d="Encontre Carlin Trilharrubra."},
    [5242] = {n="O golpe final", d="Mate Moora e Salia, e leve a Cabeça do Lorde das Sombras Fel'dan para Greta Musgo no Casco em Selva Maleva.", tgo={{"Moora"}, {"Salia"}, {"Senhor das Sombras Fel'dan"}}},
    [5243] = {n="Casas do sagrado", d="Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente.", objs={"Caixote de Suprimentos", "Caixote de Suprimentos de Stratholme"}},
    [5251] = {n="O arquivista", d="Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.", tgo={{"Arquivista Galford"}, {}}, objs={"Arquivo Escarlate"}},
    [5281] = {n="As almas inquietas", d="Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme."},
    [5282] = {n="As almas inquietas", d="Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!\nLiberte 15 Almas Inquietas, depois fale novamente com Egan.", tgo={{"Alma Inquieta"}}},
    [5306] = {n="A litofídia da caçadora sombria", d="Vá para o Pico da Rocha Negra e mate a Caçadora Sombria Vosh'gajin. Recolha a Litofídia de Vosh'gajin e fale novamente com Kilram.", tgo={{"Caçadora Sombria Vosh'gajin"}}},
    [5341] = {n="A fortuna da família Barov", d="Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa.", objs={"A Escritura de Montalvo", "A Escritura de Castro das Flechas", "A Escritura de Costa Sul", "A Escritura da Serraria Tarren"}},
    [5361] = {n="Árvore genealógica", d="Leve o Relatório de Vigia do Rochedo Chifre Longo para Nataoka Chifre Longo no Entreposto do Espírito que Anda, situado em Desolação."},
    [5381] = {n="Mão da Iruxos", d="Recolha a Caixa Demoníaca na Fortaleza Machado do Trovão e leve-a, junto com a Picareta do Diabo, para Taiga Crina Sábia na Aldeia Pescassombra.", tgo={{"Espírito Demoníaco"}}},
    [5382] = {n="Doutor Theolen Krastinov, o Carniceiro", d="Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa.", tgo={{"Doutor Theolen Krastinov"}, {}, {}}, objs={"Restos Mortais de Eva Sarkhoff", "Restos Mortais de Lucien Sarkhoff"}},
    [5386] = {n="Peixe do dia", d="Converse com Jinar'Zillen, na Aldeia Pescassombra, e depois leve 2 peixes pança-sangrenta para Nataoka Chifre Longo.", tgo={{"Jinar'Zillen"}}},
    [5441] = {n="Peões preguiçosos", d="Use o Cassetete do Encarregado nos Peões Preguiçosos enquanto estiverem dormindo. Acorde 5 peões, depois devolva o Cassetete do Encarregado ao Encarregado Thazz'ril, no Vale das Provações.", tgo={{"Peão Preguiçoso"}}},
    [5481] = {n="Beijo do Gordo", d="Colha 3 Ervas-do-emo e entregue para o Boticário-júnior Hollanda, no cemitério de Montalvo.", objs={"Erva-do-emo"}},
    [5482] = {n="Erva-do-demo", d="Colha 10 Ervas-do-demo e entregue para o Boticário-júnior Hollanda.", objs={"Erva-do-demo"}},
    [5501] = {n="Ossos do ofício", d="Entregue 10 Ossos de Kodo do Cemitério dos Kodos para Bibbly Ferrafivela no Barraco do Kormek.", objs={"Ossos de Kodo"}},
    [5511] = {n="A chave para Scolomântia"},
    [5514] = {n="Um molde que vale ouro", d="Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan."},
    [5518] = {n="O traje de ogro Gordok", d="Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel.", objs={"Felsteel Chest", "Cesta de Tanino Ôgrico", "Tesouro do Fiapo Agulhacerta"}},
    [5525] = {n="Liberdade ainda que tardia", d="Saque de: Brutamontes Gordok, Lorde-mago Gordok, Capitão Gordok", tgo={{"Brutamontes Gordok", "Lorde-mago Gordok", "Capitão Gordok"}}},
    [5526] = {n="Pedaços de Vinhavil", d="Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua."},
    [5527] = {n="Relicário da Pureza", d="Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua.", objs={"Relicário Empoeirado"}},
    [5528] = {n="O teste de sabor dos Gordok"},
    [5529] = {n="Filhotes Pestilentos", d="Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz.", tgo={{"Filhote Pestilento"}}},
    [5534] = {n="Equipamento \"Sumido\" de Kam'arawn", d="Encontre Essa Tal Runa que está com as nagas nas Ruínas de Eldarath e traga-a para Kam'arawn, em Azshara.", tgo={{"Sirena Iralisca", "Mirmidão Iralisca", "Mestre de Batalha Iralisca"}}},
    [5535] = {n="Perturbação espiritual", d="Destrua 6 Aparições Altaneiras e 6 Subliches Altaneiros. Depois, fale com Loh'atu em Azshara.", tgo={{"Aparição Altaneira"}, {"Sub-lich Altaneiro"}}},
    [5536] = {n="Uma terra repleta de ódio", d="Mate 6 Sátiros Haldarr, 2 Trapaceiros Haldarr e 2 Devotos Vil Haldarr. Depois, fale novamente com Loh'atu na fronteira do Vale Gris.", tgo={{"Sátiro Haldarr"}, {"Trapaceiro Haldarr"}, {"Devoto Vil Haldarr"}}},
    [5542] = {n="Cães demoníacos", d="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída.", tgo={{"Cão Pestilento Miúdo"}, {"Cão Pestilento"}, {"Cão Pestilento Frenético"}}},
    [5543] = {n="Céu tingido de sangue", d="Mate 30 Quirópragos e fale novamente com Tirion Fordring.", tgo={{"Quiróprago"}}},
    [5544] = {n="Carne de verme carniceiro", d="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro.", tgo={{"Verme Carniceiro", "Devorador de Carniça"}}},
    [5561] = {n="Arrebanhamento de kodos", d="Leve cinco Kodos Domados e o Kodoagrupandador para Smid Rabiscafuso no Acampamento do Rabiscafuso."},
    [5581] = {n="Portais para a Legião", d="Feche 6 portais nas Ruínas de Mannoroc e fale com Taiga Crina Sábia na Aldeia Pescassombra.", tgo={{"Guardião do Portal Demoníaco"}}},
    [5601] = {n="Irmã Pâmela", d="Encontre Pâmela Trilharrubra na Vila das Flechas."},
    [5648] = {n="Vestes da espiritualidade", d="Encontre a Bruta Kor'ja e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ela Palavra de Poder: Fortitude e fale novamente com Tai'jin no Monte Navalha.", tgo={{"Bruta Kor'ja"}}},
    [5649] = {n="Em favor da espiritualidade", d="Fale com Tai'jin em Durotar."},
    [5650] = {n="Vestes da escuridão", d="Encontre o Necroguarda Querêncio e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com Clérigo das Trevas Beryl em Montalvo.", tgo={{"Necroguarda Querêncio"}}},
    [5651] = {n="Em favor da escuridão", d="Fale com o Clérigo das Trevas Beryl nas Clareiras de Tirisfal."},
    [5652] = {n="Bagata da Fraqueza"},
    [5654] = {n="Bagata da Fraqueza", d="Fale com Ur'kyo em Orgrimmar."},
    [5658] = {n="Toque de Fraqueza"},
    [5679] = {n="Sacrifício sombrio"},
    [5680] = {n="Guarda Sombria"},
    [5722] = {n="Em busca da algibeira perdida", d="Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse."},
    [5723] = {n="Testando a força do inimigo", d="Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão.", tgo={{"Trogg Iraflama"}, {"Xamã Iraflama"}}},
    [5724] = {n="Devolvendo a algibeira perdida", d="Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão."},
    [5725] = {n="O poder de destruir...", d="Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa.", tgo={{"Sectário da Lâmina Calcinante", "Bruxo da Lâmina Calcinante"}, {"Sectário da Lâmina Calcinante", "Bruxo da Lâmina Calcinante"}}},
    [5726] = {n="Inimigos ocultos", d="Leve uma Insígnia do Tenente para Thrall em Orgrimmar.", tgo={{"Fanático da Lâmina Ardente", "Aprendiz da Lâmina Ardente"}}},
    [5727] = {n="Inimigos ocultos", d="Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar.", tgo={{"Neeru Cortafogo"}}},
    [5728] = {n="Inimigos ocultos", d="Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar.", tgo={{"Bazzalan"}, {"Jergosh, o Invocador"}}},
    [5729] = {n="Inimigos ocultos", d="Fale com Neeru Cortafogo em Orgrimmar."},
    [5730] = {n="Inimigos ocultos", d="Fale com Thrall em Orgrimmar e conte a ele o que você descobriu."},
    [5741] = {n="O Cetro de Luz", d="Pegue o Cetro de Luz e devolva-o para Azore Albamorte na torre de Ethel Rethor.", tgo={{"Vidente da Lâmina Ardente"}}},
    [5742] = {n="Redenção", d="Escute o que Tirion Fordring tem a dizer.", tgo={{"Tirion Fordring"}}},
    [5761] = {n="Mate a besta", d="Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar.", tgo={{"Taragaman, o Famélico"}}},
    [5762] = {n="Rosarães Guima", d="Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço."},
    [5763] = {n="Caçada na Selva do Espinhaço", d="Leve o Chifre de Kodo de Roon para Rosarães Guima na Selva do Espinhaço."},
    [5781] = {n="Elixir de memórias esquecidas", d="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo.", tgo={{"Mercutio Devorapodre"}}},
    [5802] = {n="A forja do Pico Penacho de Fogo", d="Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada.\nLeve a Chave-mestra Inacabada para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.", objs={"Lago de Lava do Pico Penacho de Fogo"}},
    [5804] = {n="O escaravelho de Araj", d="Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.", objs={"Filactério de Araj"}},
    [5843] = {n="Boas-vindas!", d="Entregue o Vale-brinde do Vale das Provações para Magga."},
    [5844] = {n="Boas-vindas!", d="Entregue o Vale-brinde da Aldeia Narache para Vorn Vidente do Céu."},
    [5845] = {n="Da honra perdida", d="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo.", objs={"Símbolo da Honra Perdida"}},
    [5846] = {n="Do amor e da família", d="Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura."},
    [5848] = {n="Do amor e da família", d="Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.\nLeve a pintura de volta para Tirion Fordring.", objs={"Pintura Incompleta"}},
    [5863] = {n="O Complexo Dunamalho", d="Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador.", tgo={{"Brutamontes Dunamalho"}, {"Impositor Dunamalho"}, {"Gor'marok, o Assolador"}}},
    [5881] = {n="Chamando as reservas", d="Maggran quer que você entregue uma carta a Grish Pisaléguas no Grande Elevador, que fica nos Sertões."},
    [5901] = {n="Praga de cupins!", d="Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Guel Levine no Baluarte, nas Clareiras de Tirisfal.", objs={"Cupinzeiro Grande"}},
    [5902] = {n="Praga de cupins!", d="Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais."},
    [5922] = {n="Clareira da Lua", d="Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno."},
    [5926] = {n="Atendendo o chamado", d="Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
    [5927] = {n="Atendendo o chamado", d="Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
    [5928] = {n="Atendendo o chamado", d="Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
    [5930] = {n="Espírito do Grande Urso", d="Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.", tgo={{"Espírito do Grande Urso"}}},
    [5932] = {n="De volta ao Penhasco do Trovão", d="Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos."},
    [6002] = {n="Corpo e coração", d="Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui.\nFale com Turak Runa Totem no Penhasco do Trovão quando terminar.", tgo={{"Espírito de Lunagarra"}}},
    [6022] = {n="Matar com propósito", d="Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada."},
    [6027] = {n="O Livro dos Anciãos", d="Pegue o Livro dos Anciãos e entregue-o para Azore Albamorte na torre de Ethel Rethor.", tgo={{"Lorde Kragero"}}},
    [6029] = {n="O relatório de Visteterna", d="Entregue o Relatório de Visteterna ao Oficial Argênteo Garush no Baluarte, nas Terras Pestilentas Ocidentais."},
    [6030] = {n="Duque Nicolau Zverenhoff", d="Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."},
    [6042] = {n="Pequenos transtornos da Morte-em-Vida", d="Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado.", tgo={{"Quiróprago Nóxio"}, {"Quiróprago Monstruoso"}}},
    [6061] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento.", tgo={{"Pinote Adulto"}}},
    [6062] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.", tgo={{"Mosquetusco Hediondo"}}},
    [6065] = {n="O caminho do caçador", d="Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
    [6066] = {n="O caminho do caçador", d="Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
    [6067] = {n="O caminho do caçador", d="Fale com Yaw Crina Cortante na Aldeia Casco Sangrento."},
    [6068] = {n="O caminho do caçador", d="Fale com Thotar no Monte Navalha."},
    [6069] = {n="O caminho do caçador", d="Fale com Thotar no Monte Navalha."},
    [6070] = {n="O caminho do caçador", d="Fale com Thotar no Monte Navalha."},
    [6081] = {n="Treinando a fera", d="Fale com Ormak Tiroatroz em Orgrimmar."},
    [6082] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar um Escorpídeo Encouraçado. Pratique sua habilidade e depois fale novamente com Thotar no Monte Navalha.", tgo={{"Escorpídeo Encouraçado"}}},
    [6083] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Surfatisco. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.", tgo={{"Surfatisco"}}},
    [6087] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar um Espreitador-da-pradaria. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.", tgo={{"Espreitador-da-pradaria"}}},
    [6088] = {n="Domando a fera", d="Use o Bastão de Adestramento para domar uma Rapineiro. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.", tgo={{"Rapineiro"}}},
    [6089] = {n="Treinando a fera", d="Fale com Holto Chifre Troante no Platô dos Caçadores, que fica no Penhasco do Trovão."},
    [6126] = {n="Novas lições", d="Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno."},
    [6127] = {n="A fonte principal", d="Use o Coletor Vazio do Morro de Brumedo para obter uma amostra de água de um lago no topo do morro.\nEntregue o Coletor Cheio do Morro de Brumedo a Tonga Runa Totem na Encruzilhada, nos Sertões.", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="Colhendo a cura", d="Leve 5 Raízes-telúricas e 5 Chifres de Kodo para Tonga Runa Totem na Encruzilhada para que ele possa preparar um bálsamo curativo.", tgo={{"Broto de Açoitadeira", "Iravinha"}, {"Kodo Perdido dos Sertões", "Kodo dos Sertões"}}},
    [6129] = {n="Curando os doentes", d="Use o Bálsamo Curativo para Animais em 10 Gazelas Doentes espalhadas pelo norte dos Sertões. Isso deve curá-las. Gazelas Doentes foram avistadas por toda parte a norte da estrada leste-oeste, que atravessa a Encruzilhada.", tgo={{"Gazela Doente"}}},
    [6130] = {n="O poder sobre os venenos", d="Fale novamente com Turak Runa Totem no Platô dos Anciãos, no Penhasco do Trovão."},
    [6134] = {n="Vá catar fantasmoplasma!", d="Leve 8 Fantasmoplasmas e o Caixote de Ímãs Fantasmais para Guido Zumbidorla na Desolação.", tgo={{"Espectro de Centauro"}}},
    [6142] = {n="Boa isca", d="Encontre 10 nacos de Carne de Marisco de Casca Mole e entregue-os para Mai'Lahii na Aldeia Pescassombra.", tgo={{"Tiscoral Enfurecido"}}},
    [6143] = {n="Camarão que dorme a onda leva", d="Mate 7 Mirmidões Sibilâmina, 7 Nagas Sibilâmina e 5 Feiticeiras Sibilâmina. Em seguida, fale com Drulzeger, na Aldeia Pescassombra, em Desolação.", tgo={{"Mirmidão Sibilâmina"}, {"Naga Sibilâmina"}, {"Feiticeira Sibilâmina"}}},
    [6161] = {n="O tesouro de Rodovalho!", d="Encontre a Chave Prateada de Rodovalho e a Chave Dourada de Rodovalho. Encontre e abra o Baú de Rodovalho.", tgo={{"Rastejante Estalo-seco", "Tenaz Estalo-seco"}, {"Naga Sibilâmina", "Feiticeira Sibilâmina", "Guerreiro Sibilâmina"}}},
    [6162] = {n="A última batalha de um marido", d="Mate o Suserano Ror e leve a garra dele para Dreka'Sur no Posto Peçonha, na Selva Maleva.", tgo={{"Suserano Ror"}}},
    [6164] = {n="O livro-caixa do Augustus", d="Leve o Livro-caixa do Augustus para Augustus, o Pirado, na Várzea do Medo.", objs={"Livro-caixa do Augustus"}},
    [6282] = {n="Harpias ameaçadoras", d="Maggran Ata Terra, no Retiro Rocha do Sol, quer que você mate 7 Hapias Furissague, 7 Emboscadoras Furissangue, 7 Matadoras Furissangue e 7 Plumerrantes Furissangue.", tgo={{"Harpia Furissangue"}, {"Emboscadora Furissangue"}, {"Matadora Furissangue"}, {"Plumerrante Furissangue"}}},
    [6283] = {n="O sangue das Furissangue", d="Maggram, no Retiro Rocha do Sol, quer que você mate a Estripadora Furissangue e traga os restos mortais dela como prova de seu feito.", tgo={{"Estripadora Furissangue"}}},
    [6284] = {n="Aracnofobia", d="Mate Besseleth e leve a Presa de Besseleth a Maggran no Retiro Rocha do Sol.", tgo={{"Besseleth"}}},
    [6301] = {n="Ciclo de renascimento", d="Tammra Campo de Vento, no Retiro Rocha do Sol, quer que você colete 10 Sementes de Gaia.", objs={"Semente de Gaia"}},
    [6381] = {n="Vida nova", d="Plante 10 Sementes de Gaia em Montículos de Terra de Gaia e, então, devolva as Sementes Encantadas de Gaia restantes a Tammra, no Retiro Rocha do Sol.", objs={"Monturo de Terra de Gaia"}},
    [6382] = {n="A caçada do Vale Gris", d="Fale com Senani Coração Trovejante no Posto Machadada, que fica no Vale Gris."},
    [6383] = {n="A Caçada do Vale Gris"},
    [6390] = {n="Praga de cupins!", d="Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Guel Levine, no Baluarte, que fica nas Clareiras de Tirisfal."},
    [6393] = {n="Guerra elemental", d="Leve 10 Incenderitas a Tsunomem no Retiro Rocha do Sol.", tgo={{"Espírito Errante das Chamas", "Assolador Ardente", "Destruidor Ardente"}}},
    [6394] = {n="A picareta de Thazz'ril", d="Leve a Picareta de Thazz'ril para o Encarregado Thazz'ril.", objs={"Picareta de Thazz'ril"}},
    [6395] = {n="O último desejo de Marla", d="Leve os Restos de Saulo Mitos para o Túmulo de Marla, depois fale novamente com a Noviça Elvira.", objs={"Túmulo de Marla"}},
    [6421] = {n="Ravina da Avalanche", d="Explore as profundezas da caverna na Ravina da Avalanche e colete 10 Cristais de Ressonita para que Mor'rogal, no Retiro Rocha do Sol, os analise.", objs={"Cristal de Ressonita"}},
    [6441] = {n="Chifres de Sátiro", d="Consiga 16 Chifres de Sátiro para Pixel no Posto Machadada.", tgo={{"Ladino Xaviano", "Traidor Xaviano", "Devoto Vil Xaviano"}}},
    [6442] = {n="Nagas na Praia de Zoram", d="Entregue 20 Cabeças de Iracauda a Marukai, na Praia de Zoram.", tgo={{"Mirmidão Iracauda", "Caudavalha Iracauda", "Ondarilho Iracauda"}}},
    [6461] = {n="Fome sangrenta", d="Xen'Zilla, em Malaka'Jin, precisa que você mate 10 Rastejadoras de Fundolimo e 7 Cospeçonhas de Fundolimo.", tgo={{"Rastejante de Fundolimo"}, {"Cospeçonha de Fundolimo"}}},
    [6462] = {n="Patuá troll", d="Entregue 8 Patuás Troll para Mitsuwa, no Assentamento Zoram'gar.", objs={"Baú dos Trolls"}},
    [6481] = {n="O terrano se ergue", d="Abra o esquife de ressonita com o Cristal de Ressonita Encantado e, então, mate Goggeroc. Fale novamente com Mor'rogal levando as notícias e o Cristal de Ressonita Encantado.", tgo={{"Goggeroc"}}},
    [6482] = {n="Liberdade para Ruul!", d="Escolte Ruul e, em seguida, fale com Yama Casco de Neve, no Posto Machadada."},
    [6503] = {n="Vanguardeiros do Vale Gris", d="Mate 9 Vanguardeiros do Vale Gris, depois fale novamente com Koray'bin, no Posto Machadada.", tgo={{"Vanguardeiro do Vale Gris"}}},
    [6504] = {n="As páginas perdidas", d="Encontre as 12 páginas que voaram do Manual de Operações do Retalhador e organize-as nos capítulos 1, 2 e 3. Devolva o manual a Gurda Marcafúria, que está perto do Posto Machadada."},
    [6521] = {n="Uma aliança profana", d="Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa.", tgo={{"Embaixador Malcin"}}},
    [6522] = {n="Uma aliança profana", d="Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa."},
    [6541] = {n="Apresente-se a Kadrak", d="Apresente-se a Kadrak na torre de vigia dos Sertões Setentrionais."},
    [6543] = {n="Os relatórios dos Brado Guerreiro", d="Abra o Monte de Relatórios e entregue os Relatórios dos Brado Guerreiro ao Batedor do Brado Guerreiro, o Mensageiro do Brado Guerreiro e o Pioneiro do Brado Guerreiro. Em seguida, entregue o informe sobre a situação atual que você receberá de cada um deles para Kadrak, na torre de vigia do norte dos Sertões."},
    [6544] = {n="Junte-se aos bons", d="Acompanhe Torek no ataque ao Posto Avançado Asa de Prata e sua comandante, Duriel Flameluna. Em seguida, apresente-se a Ertog Raivatusco no Posto Machadada."},
    [6545] = {n="O informe do mensageiro Brado Guerreiro"},
    [6546] = {n="O informe do pioneiro do Brado Guerreiro"},
    [6547] = {n="O informe do batedor Brado Guerreiro"},
    [6561] = {n="Vilania das Profundezas", d="Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão.", tgo={{"Senhor do Crepúsculo Kelris"}}},
    [6562] = {n="Problemas nas Profundezas", d="Fale com Je'neu Sancrea no Vale Gris."},
    [6563] = {n="A essência de Aku'mai", d="Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris.", objs={"Safira de Aku'Mai"}},
    [6564] = {n="Lealdade aos Deuses Antigos", d="Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris."},
    [6565] = {n="Lealdade aos Deuses Antigos", d="Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris.", tgo={{"Lorgus Jett"}}},
    [6621] = {n="O rei dos Torpeflora", d="Finque o Estandarte de Karang no Montículo Totêmico dos Torpeflora. Não deixe que os pelursos destruam o estandarte. Derrote o Chefe Murgut e leve o Totem de Murgut para Karang Amakkar em Zoram'gar.", tgo={{"Chefe Murgut"}}},
    [6626] = {n="A hoste do mal", d="Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos.", tgo={{"Guerreiro do Urzal"}, {"Tecespinho do Urzal"}, {"Sectário da Cabeça da Morte"}}},
    [6627] = {n="Teste de saber", d="Responda à pergunta de Braug Espírito Turvo corretamente, depois fale com ele novamente. Quando você estiver pronto, ele estará na Cordilheira das Torres de Pedra."},
    [6641] = {n="Vorsha, a Açoitadora", d="Escolte Muglash em segurança até o braseiro. Ajude-o a apagar o braseiro, e proteja-o na luta contra as nagas.\nSe cumprir a missão, volte ao Assentamento Zoram'gar e informe o Mensageiro do Brado Guerreiro da morte de Vorsha, a Açoitadora."},
    [6681] = {n="Corvoforte, a mansão", d="Leve o Selo de Corvoforte para Fahrad na Mansão de Corvoforte, que fica oculta nas colinas de Eira dos Montes.\nSua jornada testará sua sagacidade. Prepare-se.", tgo={{"Corvoforte"}}},
    [6701] = {n="Emblemas da Camarilha", d="Saque de: Assassino da Camarilha, Conjurador da Camarilha, Salteador da Camarilha", tgo={{"Assassino da Camarilha", "Conjurador da Camarilha", "Salteador da Camarilha"}}},
    [6844] = {n="Umbero, o arquivista", d="Leve o Objeto Silitídeo Incrustado para Umbero, arquivista do Círculo Cenariano, na vila de Refúgio Noturno, na Clareira da Lua."},
    [6845] = {n="Desvendando segredos do passado", d="Fale com Ravine Saturna no vilarejo de Refúgio Noturno, na Clareira da Lua."},
    [6921] = {n="Nas ruínas", d="Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.", objs={"Pedra das Profundezas"}},
    [6922] = {n="O Barão Aquanis", d="Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."},
    [6981] = {n="A lasca faiscante", d="Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.\nDepois, entregue a lasca conforme as orientações.", tgo={{"Cobogó"}}},
    [7003] = {n="Querida, encolhi os gigantes", d="Use o Ultra-encolhedor de Zorbin para deixar qualquer tipo de gigante de Feralas com um tamanho mais compacto e manejável. Colete 15 Resíduos de Miniaturização encontrados nos gigantes encolhidos e leve para Zorbin Cegasvista, que fica nas docas da Costa Esquecida, em Feralas.", tgo={{"Terrâmbulo", "Gigante do Penhasco", "Costívago"}}},
    [7028] = {n="Raízes do mal", d="Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação.", tgo={{"Centauro Amaldiçoado", "Sátiro de Pútridus", "Trapaceiro de Pútridus"}}},
    [7029] = {n="A corrupção de Torpelíngua", d="Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.\nUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.\nCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra.", tgo={{"Rebento Tóxxico"}, {}}, objs={"Poça de cristal laranja de Maraudon"}},
    [7044] = {n="Lendas de Maraudon", d="Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.\nEncontre um jeito de falar com Celebras.", tgo={{"Lorde Torpelíngua"}, {"Tóxxico", "Prole de Tóxxico"}}},
    [7046] = {n="O Cetro de Celebras", d="Ajude Celebras, o Redimido, a criar o Cetro de Celebras.\nFale com ele quando o ritual estiver concluído.", objs={"Incantation of Celebras"}},
    [7064] = {n="Corrupção da terra e dos grãos", d="Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação.", tgo={{"Princesa Theradras"}}},
    [7066] = {n="A semente da vida", d="Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida."},
    [7067] = {n="As instruções do pária", d="Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação."},
    [7068] = {n="Fragmentos de lascanegra", d="Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar.", tgo={{"Estrondor Lascanegra", "Depredador Lascanegra", "Trovejador Lascanegra"}}},
    [7201] = {n="O último elemento", d="Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais.", tgo={{"Golem de Guerra Derretido", "Golem Rasgafúria", "Constructo Armipotente"}}},
    [7441] = {n="Pusillin e o Ancião Azj'Tordin", d="Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin.\nFale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos.", tgo={{"Pusillin"}}},
    [7461] = {n="A loucura intrínseca", d="Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará.\nDestrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu.\nFale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão.", tgo={{"Immol'thar"}, {"Príncipe Tortheldrin"}}},
    [7463] = {n="Bebida arcana", d="Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu.", tgo={{"Rebentágua"}}},
    [7481] = {n="Lendas élficas", d="Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar.", objs={"Restos Descarnados de Telmius Romanesca"}},
    [7489] = {n="A teia de Letendris", d="Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas.", tgo={{"Letendris"}}},
    [7492] = {n="Aldeia Mojache", d="Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas."},
    [7498] = {n="Garona: Um Estudo sobre Furtividade e Traição", d="Devolva o livro aos legítimos donos."},
    [7499] = {n="Códice de Defesa", d="Devolva o livro aos legítimos donos."},
    [7500] = {n="Livro de Receitas do Arcanista", d="Devolva o livro aos legítimos donos."},
    [7501] = {n="A Luz e Como Ativá-la", d="Devolva o livro aos legítimos donos."},
    [7502] = {n="Sombras Agrilhoantes", d="Devolva o livro aos legítimos donos."},
    [7503] = {n="A Grande Corrida dos Caçadores", d="Devolva o livro aos legítimos donos."},
    [7504] = {n="Caçarolas: O Que a Luz Não lhe Contará", d="Devolva o livro aos legítimos donos."},
    [7505] = {n="O Choque Gélido e Você", d="Devolva o livro aos legítimos donos."},
    [7506] = {n="O Sonho Esmeralda...", d="Devolva o livro aos legítimos donos."},
    [7601] = {n="O que Niby ordena", d="Fale com Diabretim na Selva Maleva."},
    [7602] = {n="Essência Vil Impecável", d="Leve três Essências Vis Impecáveis, originárias de três locais distintos, para Diabretim na Selva Maleva.\nOs Sátiros Legashi de Azshara possuem a Essência Vil Impecável da região deles, assim como os Legionários de Jaedenar e as Sentinelas Guardas Vis da Barreira do Inferno.\nBusque as Essências Vis Impecáveis e leve-as para Diabretim, na Selva Maleva.", tgo={{"Sátiro Legashi", "Ladino Legashi", "Infernarauto Legashi"}, {"Legionário de Jaedenar"}, {"Sentinela Guarda Vil"}}},
    [7603] = {n="Núcleo Infernal de Kroshius", d="Procure os restos mortais de Kroshius no Vale das Escaras Pungentes, que fica na Selva Maleva. Ao encontrá-los, use o Fogo Vil perto deles e aguarde o retorno de Kroshius. Quando o infernal acordar, mate-o e retire do corpo dele o Núcleo Infernal de Kroshius.\nLeve o Núcleo para Niby, o Todo-poderoso na Selva Maleva.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="PROCURA-SE: Feitor Maltorius", d="Nas profundezas do Fosso de Lava do Caldeirão, na Garganta Abrasadora, você encontrará o anão traidor dos Ferro Negro chamado Feitor Maltorius.\nMate o Feitor Maltorius, arranque a cabeça dele e leve-a para o Capitão-vigia Lolo Longalcance na Garganta Abrasadora para receber sua recompensa.", tgo={{"Feitor Maltorius"}}},
    [7721] = {n="Bota dez aí, chefia!", d="Colete 10 Âmagos dos Elementais de Água dos Elementais do Mar e dos Borrifos do Mar ao longo da Costa Esquecida de Feralas, e leve-os para Zorbin Cegasvista, próximo às docas.", tgo={{"Elemental do Mar", "Borrifo do Mar"}}},
    [7722] = {n="Segue o fluxo", d="Em algum lugar do Fosso de Lava do Caldeirão você encontra as Instruções Secretas: Fluxo Ígneo que o Feitor Maltorius roubou. Encontre as instruções e devolva-as ao Mestre Ferreiro Queimatar na Garganta Abrasadora.", objs={"Instruções Secretas: Fluxo Ígneo"}},
    [7723] = {n="Malditos dedos gordos", d="Hansel Mão-pesada quer que você mate 20 Golens de Guerra Pesados.\nOs Golens de Guerra Pesados perambulam pelas áreas em torno do Caldeirão, na Garganta Abrasadora. Quando tiver matado a quantidade necessária, fale novamente com Hansel na Garganta Abrasadora.", tgo={{"Golem de Guerra Pesado"}}},
    [7724] = {n="Toco cru pegando fogo", d="Hansel Mão-pesada quer que você mate 20 Grandes Aranhas de Lava na Garganta Abrasadora. Você pode encontrá-las nos platôs e poços de lava do local.\nDepois de matar as Grandes Aranhas de Lava, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.", tgo={{"Aranha de Lava Abrasadora"}}},
    [7727] = {n="Incendossauro? É de comer?", d="Hansel Mão-pesada quer que você mate 20 Incendossauros.\nEles ocupam as poças dentro do Fosso de Lava. O Fosso de Lava fica no Caldeirão da Garganta Abrasadora.\nDepois de matar os Incendossauros, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.", tgo={{"Incendossauro"}}},
    [7728] = {n="OBJETOS ROUBADOS: Alcaraviz de Ferraria e Luneta do Espia", d="Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora.\nA única informação que você tem sobre esses itens é a seguinte: com certeza foram roubados por anões Ferro Negro. O Alcaraviz de Ferraria é uma ferramenta usada por ferreiros e a Luneta do Espia é um aparelho de monitoramento inestimável para vigias.", tgo={{"Vaporista Ferro Negro"}, {"Atalaia Ferro Negro"}}},
    [7729] = {n="TEMOS VAGAS: desbancando a concorrência", d="Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora.", tgo={{"Capataz Ferro Negro"}, {"Feitor Ferro Negro"}}},
    [7730] = {n="Infestação Zukk'ash", d="Traga 20 Carapaças de Zukk'ash para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas.", tgo={{"Aguilhante Zukk'ash", "Vespa Zukk'ash", "Trabalhador Zukk'ash"}}},
    [7731] = {n="Cravaçoite", d="Derrote Cravaçoite na Profundeza Atormentada, leve as glândulas para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas.", tgo={{"Cravaçoite"}}},
    [7732] = {n="O relatório dos Zukk'ash", d="Entregue o Relatório sobre Zukk'ash da Aldeia Mojache para Zilzibin Tamborleiro. Ele fica no Bazar de Orgrimmar."},
    [7734] = {n="Melhoria de qualidade", d="Leve 10 Pelegos de Yeti Cortifúria para Jangdor Passo Veloz na Aldeia Mojache, em Feralas.", tgo={{"Yeti Cortifúria", "Ancião de Cortifúria", "Feraz de Cortifúria"}}},
    [7738] = {n="O pelego perfeito de yeti", d="Leve o Pelego Perfeito de Yeti para Jangdor Passo Veloz na Aldeia Mojache, que fica em Feralas."},
    [7761] = {n="Comando do Mão Negra", d="Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath.\nA carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar."},
    [7815] = {n="Mordeliscas, cara!", d="Katum, o Pesqueiro, quer que você mate 15 tartarugas Mordeliscas de Água Salgada. Fale novamente com ele na Aldeia Revatusco, que fica nas Terras Agrestes, quando concluir a tarefa.", tgo={{"Mordelisca de Água Salgada"}}},
    [7816] = {n="Gammerita, cara!", d="Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate Gammerita e apanhe a Melhor Isca de Katum da carcaça.\nKatum mencionou que Gammerita circula pela costa com as outras tartarugas.", tgo={{"Gammerita"}}},
    [7828] = {n="Espreitando os espreitadores", d="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 15 Espreitadores Jubaprata e 15 Uivadores Jubaprata. Ao terminar a tarefa, fale novamente com ele.\nMarkhor mencionou que os lobos se escondem na selva das Terras Agrestes.", tgo={{"Espreitador Jubaprata"}, {"Uivador Jubaprata"}}},
    [7829] = {n="Caça às bestas", d="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 20 Ferujas Selvagens. Ao terminar a tarefa, fale novamente com ele.\nMarkhor mencionou que as Ferujas Selvagens dominam a selva nas Terras Agrestes.", tgo={{"Feruja Selvagem"}}},
    [7830] = {n="Vingar os caídos", d="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate um Senhor Celeste Bicavalha e tire dele a Pluma de Senhor Celeste. Ao terminar a tarefa, fale novamente com Markhor.\nEle mencionou que os Senhores Celestes Bicavalha são uma espécie rara que ocupa a selva nas Terras Agrestes.", tgo={{"Senhor Celeste Bicavalha"}}},
    [7839] = {n="Arruaceiros Ramatorpe", d="O Ferreiro Escoriárvore, da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre as Ferramentas Perdidas de Escoriárvore. Quando terminar, fale novamente com ele.\nVocê lembra que Escoriárvore mencionou que as ferramentas podem estar em um dos templos Ramatorpe no nordeste das Terras Agrestes. É bom procurar também em Rocha Oculta.", objs={"Ferramentas Perdidas de Escoriárvore"}},
    [7840] = {n="Banha perdeu o almoço", d="Banha na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre o Almoço do Banha. Fale novamente com ele quando a tarefa for concluída.\nBanha mencionou tê-lo esquecido na ilha ao norte. Cuidado com os trolls Ramatorpe.", tgo={{"Sequestrador Ramatorpe"}}},
    [7845] = {n="Capturaram o Ancião Presa-arrancada!", d="Primeva Presa-arrancada, da Aldeia Revatusco nas Terras Agrestes, quer que você resgate o companheiro dela, Ancião Presa-arrancada, que está em Jintha'Alor.\nDizem que ele está preso no alto de Jintha'Alor, a capital dos Ramatorpe que fica na região sul das Terras Agrestes."},
    [7846] = {n="Pegue a chave!", d="O Ancião Presa-arrancada, em Jintha'Alor, quer que você mate Hitah'ya, a Guardiã e pegue a Chave dos Grilhões para soltá-lo. Quando tiver a chave, fale novamente com o Ancião Presa-arrancada.", tgo={{"Hitah'ya, a Guardiã"}}},
    [7847] = {n="Uma resposta para Primeva Presa-arrancada", d="O Ancião Presa-arrancada, em Jintha'Alor, quer que você fale com Primeva Presa-arrancada, na Aldeia Revatusco, e avise que ele foi resgatado."},
    [7848] = {n="Harmonização com o Núcleo", d="Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo.", objs={"Fragmento de Núcleo"}},
    [7849] = {n="Angústia da separação", d="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre os restos mortais do irmão gêmeo dele. Encontre o Crânio do Guarda-caça Malkhor e os Ossos do Guarda-caça Malkhor e leve-os para o Guarda-caça Markhor.\nMarkhor mencionou que os restos mortais foram deixados para os lobos e as gosmas dos Ramatorpe. Também disse que tem um fosso cheio de gosmas em Jintha'Alor, assim como um covil de lobos. Ambos lugares ficam perto do topo do templo.", objs={"Pilha de Crânios", "Pilha de Ossos"}},
    [7850] = {n="Recipientes negros", d="Primeva Presa-arrancada da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre 10 Recipientes com Sangue Maculado em Jintha'Alor. Quando terminar, fale novamente com Primeva Presa-arrancada.", objs={"Recipiente com Sangue Maculado"}},
    [7861] = {n="Procura-se: Sacerdotisa Torpe Bagata e seus lacaios", d="Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes.\nVocê pode encontrar a Sacerdotisa Torpe Bagata e os Guardas Aman'zasi no alto de Jintha'Alor, nas Terras Agrestes.", tgo={{"Sacerdotisa Torpe Bagata"}, {"Guarda Aman'zasi Ramatorpe"}}},
    [7862] = {n="Temos vagas: Capitão da Guarda da Aldeia Revatusco", d="Você recebeu a missão de dizimar 20 Berserkers Ramatorpe, 20 Caçadores Sombrios Ramatorpe, 20 Bebe-sangue Ramatorpe e 20 Devoradores de Almas Ramatorpe.\nCaso conclua a missão, fale com Primeva Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.", tgo={{"Berserker Ramatorpe"}, {"Caçador Sombrio Ramatorpe"}, {"Bebe-sangue Ramatorpe"}, {"Devorador de Almas Ramatorpe"}}, star={"Runa do Capitão da Guarda", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="O tesouro de Shen'dralar", d="Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Resgate sua recompensa!"},
    [8151] = {n="O amuleto do caçador", d="Encontre Ogtinc em Azshara."},
    [8153] = {n="Galhada de ginete", d="Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath.", tgo={{"Ginete Cascomusgo"}}},
    [8231] = {n="Furando onda", d="Leve 6 Escamas de Fura-ondas para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tgo={{"Jovem Fura-ondas", "Fura-ondas", "Grande Fura-ondas"}}},
    [8232] = {n="O draco verde", d="Leve o Dente de Morphaz para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tgo={{"Morphaz"}}, star={"Olho de Demossauro", {"HUNTER"}}},
    [8233] = {n="Um pedido simples", d="Fale com Lorde Jorach Corvoforte na Mansão de Corvoforte."},
    [8234] = {n="Saco lazúli lacrado", d="Recupere o Saco Lazúli Lacrado com o Xamã Presamatos, em Azshara. Então o leve para o Arquimago Tauriel, também em Azshara.", tgo={{"Xamã Presamatos", "Blackmaw Shaman"}}},
    [8235] = {n="Fragmentos codificados", d="Leve 10 Fragmentos Codificados para o Arquimago Tauriel em Azshara.", tgo={{"Gosma Florestal"}}},
    [8236] = {n="A chave lazúli", d="Leve a Chave Lazúli para o Lorde Jorach Corvoforte.", tgo={{"Morphaz"}}, star={"Clâmide Quiropúsculo", {"ROGUE"}}},
    [8250] = {n="Magiaria", d="Procure Sanath Lim-yo e consiga o transporte para ver o Arquimago Tauriel."},
    [8251] = {n="Pó Mágico", d="Leve 10 Poeiras Reluzentes para o Arquimago Tauriel.", tgo={{"Topógrafo Sanguinélfico", "Recuperador Sanguinélfico", "Defensor Elfo Sangrento"}}},
    [8252] = {n="Coral de sirenas", d="Obtenha 6 Corais Encantados e entregue-os ao Arquimago Tauriel.", tgo={{"Sirena Iralisca"}}},
    [8253] = {n="A destruição de Morphaz", d="Recupere o Estilhaço Arcano de posse de Morphaz e fale novamente com o Arquimago Tauriel.", tgo={{"Morphaz"}}, star={"Rubi de Fogo", {"MAGE"}}},
    [8254] = {n="Ajuda aos cenarianos", d="Encontre Ogtinc em Azshara."},
    [8255] = {n="Ginetes sagrados", d="Obtenha 4 Glândulas de Ginete Saudável leve-as para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath.", tgo={{"Ginete Cascomusgo"}}},
    [8256] = {n="A linfa de morte-viva", d="Obtenha uma Linfa de Morte-viva para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tgo={{"Zumbi Zanzil", "Caçador Zanzil", "Esfolador Descarnado"}}},
    [8257] = {n="Sangue de Morphaz", d="Mate Morphaz no templo submerso de Atal'Hakkar e leve o sangue dele para Greta Musgo no Casco na Selva Maleva. A entrada do templo submerso fica no Pântano das Mágoas.", tgo={{"Morphaz"}}, star={"Contas de Oração Abençoadas", {"PRIEST"}}},
    [8276] = {n="A retomada de Silithus", d="Apresente-se à Arauto do Vento Chifre Altivo no Forte Cenariano, em Silithus."},
    [8277] = {n="Peçonha mortal do deserto", d="Belhatriz Corredente, no Forte Cenariano em Silithus, quer que você traga 8 Aguilhões de Escorpídeo Petraçoite e 8 Presas de Rastejante da Areia. Fale com ela quando tiver completado a tarefa.", tgo={{"Escorpídeo Petraçoite"}, {"Rastejante da Areia"}}},
    [8278] = {n="A última esperança de Noggel", d="Belhatriz Corredente, no Forte Cenariano em Silithus, quer que você consiga 3 Aguilhões de Tenaz Petraçoite, 3 Aguilhões de Esfolador Petraçoite e 3 Presas de Espreitadora de Rocha.", tgo={{"Esfolador Petraçoite"}, {"Tenaz Petraçoite"}, {"Espreitadora de Rocha"}}},
    [8280] = {n="Defendendo as linhas de suprimento", d="O Arauto do Vento Chifre Altivo, no Forte Cenariano, quer que você mate 15 Dragatacas.", tgo={{"Dragataca"}}},
    [8281] = {n="Aumentando a segurança", d="O Arauto do Vento Chifre Altivo, no Forte Cenariano, quer que você mate 20 Dragasmagas.", tgo={{"Dragasmaga"}}},
    [8284] = {n="O mistério do crepúsculo", d="A Geóloga Matarriso, no Forte Cenariano, quer que você recolha 8 Fragmentos de Tabuleta do Crepúsculo.", objs={"Fragmento de Tabuleta do Crepúsculo"}},
    [8285] = {n="O desertor", d="Leve a tabuleta restaurada para o Eremita Ortell em Silithus."},
    [8318] = {n="Comunicação secreta", d="Traga 10 Textos Cifrados do Crepúsculo para Bor Juba Agreste no Forte Cenariano.", tgo={{"Guardião do Crepúsculo Havunth", "Vingador do Crepúsculo", "Geolorde do Crepúsculo"}}},
    [8365] = {n="Chapéus de pirata, io-hô!", d="Sissi Ashando quer que você colete 20 Chapéus de Pirata dos Mares do Sul e leve-os para ela no Porto de Bondebico, em Tanaris.", tgo={{"Pirata dos Mares do Sul", "Flibusteiro dos Mares do Sul", "Estivador dos Mares do Sul"}}},
    [8366] = {n="Recadinho dos Mares do Sul", d="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você mate 10 Piratas dos Mares do Sul, 10 Flibusteiros dos Mares do Sul, 10 Estivadores dos Mares do Sul e 10 Espadachins dos Mares do Sul.", tgo={{"Pirata dos Mares do Sul"}, {"Flibusteiro dos Mares do Sul"}, {"Estivador dos Mares do Sul"}, {"Espadachim dos Mares do Sul"}}},
    [8411] = {n="Dominando os elementos", d="Leve os elementos terra, ar, fogo e água para Bath'rah, o Vigia dos Ventos.", tgo={{"Redemoinho de Poeira", "Exilado Trovejante", "Ciclonium"}, {"Elemental da Rocha", "Fúria Pétrea", "Escravo Elemental"}, {"Embaixador Infernus", "Exilado em Chamas", "Espírito Errante das Chamas"}, {"Elemental Inferior da Água", "Exilado Vagalhante", "Guardião Evocado"}}},
    [8412] = {n="Totem de espírito", d="Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito.", tgo={{"Abutre Carniceiro", "Tocaieira Carniceira", "Tocaieira Rasterruça"}, {"Abutre Carniceiro", "Urso Preto Doente", "Urso-cinzento Doente"}}},
    [8413] = {n="O Vodu", d="Leve as Penas Vodu para Bath'rah, o Vigia dos Ventos.", tgo={{"Talho", "Zul'Lor", "Talho"}, {"Hukkah", "Mirran", "Hukkah"}, {"Zolo", "Lorro", "Lorro"}}, star={"Espírito de Água Enamorado", {"SHAMAN"}}},
    [8417] = {n="Um espírito atormentado", d="Fale com o Herói Caído da Horda na entrada da Barreira do Inferno."},
    [8420] = {n="Quente e pinicante", d="Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva.", tgo={{"Caçador Vil", "Sentinela Guarda Vil", "Sátiro Legashi"}}},
    [8421] = {n="O enchimento errado", d="Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva.", tgo={{"Errante de Ferrárbol", "Pisoteador de Ferrárbol", "Protetor Dessecado"}, {"Gosma Maculada"}}},
    [8422] = {n="Penas de troll", d="Leve um total de 6 Penas Vodu dos trolls do templo submerso.", tgo={{"Talho", "Zul'Lor", "Talho"}, {"Hukkah", "Mirran", "Hukkah"}, {"Zolo", "Lorro", "Lorro"}}, star={"Ceifalmas", {"WARLOCK"}}},
    [8423] = {n="Parentesco guerreiro", d="Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tgo={{"Javiltusco"}}},
    [8424] = {n="Guerra aos devotos da sombra", d="Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tgo={{"Adepto Devoto da Sombra"}, {"Sectário Devoto da Sombra"}, {"Capanga Devoto da Sombra"}}},
    [8425] = {n="Penas Vodu", d="Leve as Penas Vodu dos trolls do Templo Submerso para o Herói Caído da Horda.", tgo={{"Talho", "Zul'Lor", "Talho"}, {"Hukkah", "Mirran", "Hukkah"}, {"Zolo", "Lorro", "Lorro"}}, star={"Frasco de Diamante", {"WARRIOR"}}},
    [8460] = {n="Aliando-se aos Presamatos", d="Grazle quer que você prove seu valor matando 6 Guerreiros de Lenha Morta, 6 Desbravadores de Lenha Morta e 6 Jardineiros de Lenha Morta. Quando você terminar, fale novamente com ele na parte sul da Selva Maleva, perto do Santuário Esmeralda.", tgo={{"Guerreiro de Lenha Morta"}, {"Desbravador de Lenha Morta"}, {"Jardineiro de Lenha Morta"}}},
    [8461] = {n="Lenha Morta do Norte", d="Nafien quer que você mate 6 Vigias do Covil de Lenha Morta, 6 Vingadores de Lenha Morta e 6 Xamãs de Lenha Morta. Fale novamente com ele na parte norte da Selva Maleva, perto da entrada do Domínio dos Presamatos.", tgo={{"Vigia do Covil de Lenha Morta"}, {"Vingador de Lenha Morta"}, {"Xamã de Lenha Morta"}}},
    [8462] = {n="Fale com Nafien", d="Viaje para o norte ao longo da estrada principal em Selva Maleva e fale com o pelurso chamado Nafien. Ele monta guarda diante da entrada do Domínio dos Presamatos."},
    [8464] = {n="Atividade Invernosa", d="Salfa quer que você mate 8 Xamãs Invernosos, 8 Vigias do Covil dos Invernosos e 8 Ursinos Invernosos. Salfa está perto da entrada do Domínio dos Presamatos, em Hibérnia.", tgo={{"Xamã Invernoso"}, {"Vigia do Covil dos Invernosos"}, {"Ursino Invernoso"}}},
    [8465] = {n="Fale com Salfa", d="Viaje pelo Domínio dos Presamatos até chegar a Hibérnia. Fale com Salfa, que está de guarda em frente à entrada do Domínio dos Presamatos."},
    [8551] = {n="O baú do capitão", d="Leve o Baú do Smotts para Hacklebury Smotts na Angra do Butim.", tgo={{"Gorlash"}}},
    [9051] = {n="Exame de intoxicação", d="Espete um Demossauro com uma Farpa para Demossauro. Fale novamente com Torwa Mateiro na Cratera Un'goro depois que tiver terminado a tarefa."},
    [9052] = {n="Veneno de Pétala Sangrenta", d="Colete 8 Cogumelos Vermelhos e 8 Ferrões de Gorishi e fale novamente com Torwa Mateiro na Cratera Un'Goro.", tgo={{"Vespa Gorishi", "Gorishi Aguilhante"}, {}}, objs={"Broto de Pétala Sangrenta"}},
    [9053] = {n="Um ingrediente melhor", d="Consiga uma Trepadeira Pútrida do guardião no fundo do Templo Submerso e fale novamente com Torwa Mateiro.", tgo={{"Atal'alarion"}}, star={"Pelagem Cinzenta", {"DRUID"}}},
    [65593] = {n="Corações dos amantes", d="Leve os corações de Avelina Lily e Isaac Pessoa para Silvério Hidalgo no Templo dos Malditos.", tgo={{"Avelina Lily"}, {"Isaac Pessoa"}}},
    [65597] = {n="A vinculação", d="Usando os Corações dos Amantes, evoque e subjugue um íncubo. Depois, devolva os Corações dos Amantes para Silvério Hidalgo no Distrito da Magia na Cidade Baixa.", tgo={{"Íncubo Evocado"}}},
    [65601] = {n="O amor machuca", d="Fale com Magar em Orgrimmar."},
    [65604] = {n="A vinculação", d="Usando o Lenço Fenecido, evoque e subjugue um íncubo. Depois, devolva o Lenço Fenecido para Gan'rul Olho de Sangue em Orgrimmar.", tgo={{"Íncubo Evocado"}}},
    [65610] = {n="A esperança é a última que morre", d="Investigue o Lago Céu Caído, que fica no Vale Gris, e relate suas descobertas a Gan'rul Olho de Sangue em Orgrimmar.", tgo={{"Move-pedras Umbrárvore", "Rasga-casca Umbrárvore", "Oráculo Umbrárvore"}}},
    [78261] = {n="A Trompa de Xelthos", d="Encontre a Trompa de Xelthos dentro da Bastilha da Presa Negra. Depois, leve-a até o esconderijo de C perto do Vilarejo Lenhardente. Você precisa fazer isso sem ajuda."},
    [78270] = {n="Goblin Lockpicks", d="Saque de: Desmatador da Empreendimentos S.A., Operador da Empreendimentos S.A., Madeireiro da Empreendimentos S.A.", tgo={{"Desmatador da Empreendimentos S.A.", "Operador da Empreendimentos S.A.", "Madeireiro da Empreendimentos S.A."}}},
    [78307] = {n="A Trompa de Xelthos", d="Log"},
    [78676] = {n="The Eye of Bhossca", d="Usar/coletar: Padlocked Reliquary", objs={"Padlocked Reliquary"}},
    [78699] = {n="The Eye of Bhossca", d="Log"},
    [78830] = {n="Terror dos céus do deserto", d="Saque de: Gharrik", tgo={{"Gharrik"}}},
    [79229] = {n="Roubo na estrada", d="Encontre alguém em Desolação que saiba sobre o acampamento saqueado."},
    [79235] = {n="Em fuga", d="Encontre um dos bandidos de Desolação."},
    [79236] = {n="Cherry for Your Thoughts?", d="Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story."},
    [79360] = {n="Auxílio elemental", d="Derrote Charlga Talhaflanco no Urzal dos Tuscos e colete informações sobre os planos dos javatuscos.", tgo={{"Charlga Talhaflanco"}}},
    [79361] = {n="Tempestade, terra e fogo", d="Colete 5 Totens do Fogo Deturpados, 5 Totens da Terra Deturpados, 5 Totens do Ar Deturpados e 5 Totens da Água Deturpados para Pradosa Fita Nuvens em Mil Agulhas.", tgo={{"Saltapoças Lamapina", "Murloc Lamapina", "Guerreiro Lamapina"}, {"Moralama dos Perdidos", "Pescador dos Perdidos", "Caçador dos Perdidos"}, {"Batecrânios da Abóbada de Pedra", "Quebraossos da Abóbada de Pedra", "Xamã da Abóbada de Pedra"}, {"Cavalgante Maraudino", "Espancador Maraudino", "Ventilhã Maraudina"}}},
    [79364] = {n="De olhos no céu", d="Encontre Pradosa Fita Nuvens em Mil Agulhas."},
    [79365] = {n="With Wind Beneath Your Wings", d="Return to Rau Cliffrunner in Thousand Needles at Freewind Post."},
    [79366] = {n="Heed My Call", d="Saque de: Ravaging Tempest", tgo={{"Ravaging Tempest"}}},
    [79442] = {n="The Tempest's Weapons", d="Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", star={"Ira da Tempestade / Garra do Relâmpago / Garra do Arauto das Marés"}},
    [80411] = {n="The Talisman of Kazdor", d="Usar/coletar: Spellbound War Chest", objs={"Spellbound War Chest"}},
    [80526] = {n="Fool Me Twice", d="Speak to Fahrad when you're ready to hear his plan."},
    [82084] = {n="A Lesson in Literacy", d="Saque de: Feruja Feroz, Feruja Primitiva, Feruja Selvagem", tgo={{"Feruja Feroz", "Feruja Primitiva", "Feruja Selvagem"}, {"Aguilhante Zukk'ash", "Vespa Zukk'ash", "Trabalhador Zukk'ash"}, {"Zumbi de Zul'Farrak"}}},
    [84398] = {n="A Study of the Light", d="Usar/coletar: Livro", objs={"Livro"}},
    [86576] = {n="Berloques Furissangue", d="Leve 15 Pedras Solares Lampejantes para Mor'rogal.", tgo={{"Harpia Furissangue", "Plumerrante Furissangue", "Matadora Furissangue"}}},
    [90902] = {n="Redescobrindo a Luz", d="Cure 5 Necroguardas Feridos com sua habilidade Luz Sagrada.", tgo={{"Necroguarda Ferido"}}},
    [91208] = {n="Aprender a conviver", d="Encontre a Paladina Assustada em Plangemortis.", tgo={{"Paladina Assustada"}}},
    [91209] = {n="Continue seu treinamento", d="Siga pela estrada rumo a leste, saindo de Plangemortis, até chegar a Montalvo. Apresente-se a Shária Calmafonte para continuar seu treinamento.", tgo={{"Shária Calmafonte"}}},
    [91282] = {n="Um segundo lar", d="Encontre a fortaleza da Bastilha de Bandarion e apresente-se a Bretônio Samuel."},
    [91285] = {n="Murlocs nos portões", d="Mate 8 Atacantes Pinavil e 8 Videntes Pinavil e fale novamente com Bretônio Samuel quando terminar.", tgo={{"Atacante Pinavil"}, {"Vidente Pinavil"}}},
    [91294] = {n="Um passeio pelo pátio", d="Fale com os moradores da Bastilha de Bandarion.", tgo={{"Hilda, a Devastadora"}, {"Jorin Croge"}, {"Abner Solliden"}, {"Danitha Morr"}}},
    [91316] = {n="Reformas", d="Colete 12 pedaços de Lenha Robusta do Vale das Sombras nas Clareiras de Tirisfal.", objs={"Pilha de Madeira"}},
    [91317] = {n="Os manchados", d="Mate 8 Labutadores Manchados, 6 Zelotes Manchados e colete a cabeça do Comandante Rudolph Gelhardt nas Clareiras de Tirisfal.", tgo={{"Rudolfo Gelhardt"}}},
    [91497] = {n="Seals of the Sin'dorei", d="Saque de: Lieutenant Suncrest, Magíster Falcoelmo, Ranger Lydrea", tgo={{"Lieutenant Suncrest"}, {"Magíster Falcoelmo"}, {"Ranger Lydrea"}}},
    [91500] = {n="An Explosive Gambit", d="Saque de: Maga Rimtori", tgo={{"Maga Rimtori"}}},
    [91531] = {n="Revenge Exacted", d="Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar."},
    [91858] = {n="Incidente diplomático", d="Vá até o Sepulcro, na Floresta de Pinhaprata, e fale com Trevano Rol dos membros desaparecidos da Harmonia Telúrica."},
