    [97253] = {n="Peças e pedaços", d="Colete 5 Punhados de Peças Complicadas do acampamento pirata superior, ao sul da Vila Catraca, e depois fale novamente com Wrenix, o Ignóbil, na Vila Catraca.", objs={"Pilha de Peças Complicadas"}},
    [97257] = {n="Clamor do fogo", d="Espere Olariaan iniciar o ritual no Braseiro da Oferenda e siga as instruções dele.\nVocê precisa levar a Chama Eterna a Valanaar antes que o tempo se esgote.", tgo={{"Braseiro da Oferenda"}, {"Braseiro da Chama Eterna"}}, star={"Totem das Chamas Carregadas", {"SHAMAN"}}},
    [97265] = {n="Ódio aos Furiódios", d="Derrote uma variedade de sátiros Furiódios em Sargeron, em Desolação, e depois fale novamente com Ara'kai na Aldeia Pescassombra.", tgo={{"Trapaceiro Furiódio"}, {"Infernarauto Furiódio"}, {"Assombrante Furiódio"}, {"Devoto Vil Furiódio"}, {"Errante Furiódio"}}},
    [97279] = {n="Armas extraviadas", d="Colete 6 Armas de Treino Abandonadas e vá até Kzan Cortarrasga, no Covil.", objs={"Arma de Treino Abandonada"}},
    [97281] = {n="Uma tempestade se formando", d="Leve o Orbe da Tempestade Opaco para Rezlak perto do Barranco da Ravina Seca."},
    [97282] = {n="Potencial trovejante", d="Leve 5 Órgãos de Lagarto Trovejante Carregados para Rezlak perto do Barranco da Ravina Seca.", tgo={{"Lagarto Trovejante", "Pelego de Relâmpago", "Halikor"}}},
    [97287] = {n="Negociações arguciosas", d="Fale com a Imagem da Arquimaga Modera nos arredores de Dalaran."},
    [97288] = {n="Tormento sem fim", d="Entregue a Cabeça Abominável ao Mestre-boticário Faranello na Cidade Baixa."},
    [97289] = {n="Tormento sem fim", d="Leve a Cabeça do Barão ao corpo de Othmar na Cidade Baixa."},
    [97290] = {n="Tormento sem fim", d="Relate suas descobertas ao Mestre-boticário Faranello na Cidade Baixa."},
    [97291] = {n="Tormento sem fim", d="Obtenha um Morrião Tóxico com Clorinda Grisette no Distrito Comercial, Pustulerva perto do local de Treinamento de Herborismo, e Essência da Agonia com o comerciante de venenos no Distrito dos Ladinos para entregar ao Mestre-boticário Faranello na Cidade Baixa.", objs={"Pustulerva"}},
    [97292] = {n="Tormento sem fim", d="Injete Soro Sibilante nos mecanismos sobre o corpo de Othmar para o Mestre-boticário Faranello.", objs={"Othmar's Head"}},
    [97327] = {n="Blackmaw Pouches", d="Saque de: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", tgo={{"Blackmaw Berserker", "Blackmaw Thrall", "Blackmaw Headhunter"}}},
    [97328] = {n="Algo de valor", d="Recupere 8 Carregamentos Roubados nas Ruínas de Zul'Kanda, na Selva do Espinhaço, e entregue a carga recuperada a alguém na Angra do Butim."},
    [97329] = {n="Cadê a chave?", d="Obtenha a Chave Primitiva com os trolls das Ruínas de Zul'Kanda, na Selva do Espinhaço, e leve-a a Zimmix Cospefaísca.", tgo={{"Batedor Sanguescalpo", "Caçador Sanguescalpo", "Berserker Sanguescalpo"}}},
    [97331] = {n="A grande fuga de Zimmix", d="Escolte Zimmix Cospefaísca para longe das Ruínas de Zul'Kanda. Depois, fale com o Mestre Portuário Lozgil, na Angra do Butim, sobre o resgate bem-sucedido."},
    [97332] = {n="Confiando duas vezes em quem não merece", d="Entregue o Pacote Reprocessado Duas Vezes ao Mestre Portuário Carrapeto no Porto Detonapavio, nas Sendas do Rio."},
    [97386] = {n="The Offense of Grom'gol", d="Matar: Feitífice Mosh'Ogg, Fomentador de Guerra Mosh'Ogg, Espancador Mosh'Ogg, Xamã Mosh'Ogg", tgo={{"Feitífice Mosh'Ogg"}, {"Fomentador de Guerra Mosh'Ogg"}, {"Espancador Mosh'Ogg"}, {"Xamã Mosh'Ogg"}}},
    [97453] = {n="Passando a roçadeira", d="Mate 6 Ervas Carnívoras ao sul de Grom'gol e depois informe a mãe de Gemmil.", tgo={{"Erva Carnívora"}}},
    [97485] = {n="Tradições do Penhasco", d="Compre um Maço de Ervas com Nida, a herborista, um Maço de Galhos de Cedro com Nata, a fornecedora de encantamento, Fio de Tendão com Mahu, o fornecedor de couraria, e Pederneira e Lenhas Cerimoniais com Naal, o fornecedor de culinária.\nCombine os itens e espalhe o incenso do Platô dos Caçadores.", objs={"Incensório"}},
    [97530] = {n="Deveres dos Dunamalho", d="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você um recupere bracelete particularmente brilhante que foi perdido próximo ao complexo ôgrico de Dunamalho.", tgo={{"Ogro Dunamalho", "Impositor Dunamalho", "Ogro-mago Dunamalho"}}},
    [97534] = {n="Gritty Business", d="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan."},
    [97539] = {n="Suturas de seda", d="Devolva 12 Sedaracnas Cirúrgicas ao Doutor Victor Zerbini na Ruína do Martelo, no Planalto Arathi.", tgo={{"Rastejante das Planícies", "Rastejante Gigante das Planícies"}}},
    [97558] = {n="Pelegos para os Renegados", d="Leve 8 Membranas de Asa de Quiropúsculo, 6 Pelego de Cão das Trevas e 3 Pele de Murloc Pinavil para Lenita Ravais.", tgo={{"Grande Quiropúsculo", "Quiropúsculo Vampírico"}, {"Cão das Trevas Decrépito", "Cão das Trevas Amaldiçoado"}, {"Oráculo Menor Pinavil", "Moralodo Pinavil"}}},
    [97908] = {n="Introdução ao acampamento: Esfolamento", d="Fale com Thuwd em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", tgo={{"Thuwd"}}},
    [97936] = {n="Introdução ao acampamento: Esfolamento", d="Fale com Yonn Corte Profundo na Aldeia Casco Sangrento para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", tgo={{"Yonn Corte Profundo"}}},
    [98024] = {n="Jornada para a Encruzilhada", d="Fale com Thork na Encruzilhada, que fica nos Sertões."},
    [98069] = {n="Suprimentos de Vento Livre Roubados", d="Leve 8 Suprimentos de Vento Livre Roubados para Jandia, na Aldeia Vento Livre."},
    [98070] = {n="Um fim para as guinchadoras", d="Mate 5 Harpias Guinchadoras, 5 harpias Plumerrantes Guinchadoras e 5 harpias Arautas do Vento Guinchadoras.", tgo={{"Harpia Guinchadora"}, {"Plumerrante Guinchadora"}, {"Arauto do Vento Guinchador"}}},
    [98093] = {n="Trabalho de campo", d="Sulhasa, na parte sul dos Sertões, quer que você elimine 7 Lagartos Borrascouro e 7 Espreitadores Presavaia na área para que ela possa descer da árvore com segurança.", tgo={{"Espreitador Presavaia"}, {"Borrascouro"}}},
    [98094] = {n="Suporte aos batedores", d="A Alta-executora Darthalia quer que você entregue as ordens atualizadas para o Sicário Masoj, ao sul da Serraria Tarren, nos arredores de Dun Garok."},
    [98095] = {n="Vantagens valiosas", d="O Sicário Masoj precisa que você deixe as três Ampolas de Boticário nos picos ao redor do Contraforte de Eira dos Montes e depois retorne até ele."},
    [98298] = {n="A loucura de Arugal", d="Leve 6 Pedaços de Worgen a Dalar Tessalba no Sepulcro.", tgo={{"Uivassangue Lunafúria"}}},
    [98299] = {n="Combate à proliferação", d="Mate 5 Refugiados Adoentados e 5 Refugiados Famintos para Dalar Tessalba no Sepulcro.", tgo={{"Refugiado Faminto"}, {"Refugiado Adoentado"}}},
    [98340] = {n="O Espírito do Grande Felino", d="Fale com Dendrite Stellardor no vilarejo do Refúgio Noturno, na Clareira da Lua."},
    [98341] = {n="O grande espírito felino pairavento", d="Procure o Avatar de Saeyleenan na porção meridional da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do gato pairavento."},
    [98342] = {n="O Espírito do Grande Felino", d="Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Espírito do Grande Felino.", objs={"Relíquia da Presa", "Relíquia da Garra", "Relíquia da Sombra Silenciosa"}},
    [98362] = {n="Para o Penhasco do Trovão", d="Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos."},
    [98389] = {n="Uma luz na escuridão", d="Liberte 6 Vítimas Encasuladas na Caverna da Teia da Noite para Aramis Cerramartelo em Plangemortis."},
    [98404] = {n="O grande espírito felino pairavento", d="Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Avatar de Saeyleenan.", objs={"Relíquia da Presa", "Relíquia da Garra", "Relíquia da Sombra Silenciosa"}},
    [98405] = {n="O Espírito do Grande Felino", d="Procure o Espírito do Grande Felino na porção meridional da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do gato."},
    [98424] = {n="Anotações do Geringonça", d="Colete o restante das páginas do Supervisor Geringonça dentro da Mina da Empreendimentos S.A. e leve-as a Morin Espreita Nuvem, perto da Aldeia Casco Sangrento.", objs={"Instruções de Operação do Retalhador", "Melhores Práticas para Operações nos Sertões", "Um Tal Gerenzo, das Torres de Pedra"}},
    [98427] = {n="Encerrando as operações", d="Leve a Chave de Fio-afiado a Morin Espreita Nuvem, nos arredores da Aldeia Casco Sangrento.", tgo={{"Limpa-tranqueira da Empreendimentos S.A"}}},
    [98430] = {n="Os Passo-longo", d="Ajude Perith Casco Feroz a escapar do Rochedo Jubalba e informe Caerne Casco Sangrento, no Penhasco do Trovão, de que Perith está a salvo."},
    [98435] = {n="Relatório de Chifre Troante", d="Leve o Relatório de Chifre Troante ao Arquidruida Hamuul Runa Totem, no Penhasco do Trovão."},
    [98575] = {n="Tainted Tablet", d="Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials."},
    [98576] = {n="Glyphic Parchment", d="Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
    [98601] = {n="Um caminho árduo", d="Leia o Pergaminho Consagrado e fale com Aramis Cerramartelo na igreja de Plangemortis."},
    [98738] = {n="Bênçãos do Grande Espírito Felino Pairavento", d="Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua."},
    [98739] = {n="Bênçãos do Espírito do Grande Felino", d="Fale com Dendrite."},
    [98823] = {n="Eco telúrico", d="Leve a Relíquia Titânica para Muln Terrafúria no Platô do Vigia dos Céus, no noroeste de Mulgore."},
    [99048] = {n="A mão desaparecida", d="Encontre Heglan Sombrolho ao norte da Bastilha Tiragarde."},
    [99049] = {n="Ameaça vinda de baixo", d="Encontre sinais do que atacou Heglan Sombrolho.", objs={"Adaga Abandonada", "Destroços Estranhos", "Parte de Arma"}},
    [99051] = {n="Ameaça vinda de baixo", d="Colete 9 Espinhapinas de Naga.", tgo={{"Batedor Iralisca", "Serviçal Iralisca"}}},
    [99052] = {n="Ameaça vinda de baixo", d="Mate o Gigante do Mar na costa norte de Durotar e traga uma prova do seu feito.", tgo={{"Aggor, o Jovem"}}},
    [99079] = {n="Passo-longo Malah", d="Encontre a Passo-longo Malah Vento Longo a leste da Aldeia Casco Sangrento, perto da divisa de Mulgore."},
    [99080] = {n="Expulse todos", d="Mate 6 Centauros Galath e 4 Vanguardeiros Galath e leve a cabeça de Herak, o Pilhador, até Baine Casco Sangrento.", tgo={{"Centauro Galath"}, {"Vanguardeiro Galath"}, {"Herak, o Pilhador"}}},
    [99081] = {n="Augúrios sinistros", d="Leve o Relatório da Passo-longo Malah ao Valente Trilha Selvagem na Aldeia Casco Sangrento."},
    [99082] = {n="O Grande Chefe", d="Peça uma audiência com o Grande Chefe Caerne Casco Sangrento no Penhasco do Trovão."},
    [99101] = {n="Nosso inimigo ancestral", d="Leve o Relatório da Passo-longo Malah a Baine Casco Sangrento."},
    [99108] = {n="Treino de pugilato", d="Derrote outros 3 jogadores em duelos ou Guerreiros Novatos para Tang Casco de Pedra.", tgo={{"Guerreiro Novato"}}},
    [99123] = {n="Perdida nas sombras", d="Ajude Pal'juh a escapar do Penedo de Kolkar e avise o Mestre Vornal na Aldeia Sen'jin quando conseguir."},
    [99134] = {n="Disciplina", d="Puna 5 Necroguardas para o Executor Zigano."},
    [99141] = {n="Paciência", d="Obtenha os relatórios do Necroguarda Dinis, do Necroguarda Kristof e de Gordo para o Executor Zigano.", tgo={{"Necroguarda Dinis"}, {"Necroguarda Kristof"}, {"Gordo"}}},
    [99142] = {n="Erva de Tumba", d="Colete 5 Ervas de Tumba e entregue para o Boticário-júnior Hollanda.", objs={"Erva de Tumba"}},
    [99156] = {n="Patrulha da retaguarda", d="Leve o Coração de Talharretalha até a Necroguarda Lina.", tgo={{"Talharretalha"}}},
    [99187] = {n="The Reliquary of Tyr", d="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", star={"Sword of Mourning", {"PALADIN"}}},
    [99411] = {n="Kyle sumiu!", d="Ahab Casco Trigo, na Aldeia Casco Sangrento em Mulgore, quer que você alimente o bichinho de estimação dele, Kyle, o Frenético.\nAlimente Kyle com Carne Tenra de Moa e fale novamente com Ahab Casco Trigo.", tgo={{"Kyle, o Frenético"}}},
  },
